import{u as e}from"./useBreadcrumb-b65b21cb.js";import{_ as t}from"./LocationPinIcon.vue_vue_type_script_setup_true_lang-c1788f84.js";import{o as n,i as o,p as s,t as a,q as i,r,g as l,j as c}from"./store-24eef8f3.js";import{d,b as p,Q as u,o as m,c as f,a as b,f as h,z as g,u as x,e as y,g as v,_ as w}from"./index-5fcdbd77.js";import"./DefaultSvg.vue_vue_type_script_setup_true_lang-d5a8994e.js";import"./tslib.es6-9fe0c711.js";const S="<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>売場ロケーション管理 プロトタイプ</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;700&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"><\/script>\n<style>\n  /* ===== PlanoCycle デザイントークン ===== */\n  :root {\n    --theme-110:#216e51; --theme-100:#248661; --theme-90:#3d9271; --theme-80:#539e81;\n    --theme-60:#7cb6a0; --theme-50:#93c2b0; --theme-40:#aed2c4; --theme-30:#bddbd0;\n    --theme-20:#d3e7df; --theme-15:#deede7; --theme-10:#e9f3ef; --theme-5:#f3f9f7;\n    --black-100:#2f4136; --black-70:#4f665b; --black-40:#7b968b; --black-30:#8aa69b;\n    --red-110:#d24765; --red-100:#e55779; --red-30:#f7cdd7; --red-15:#fbe6eb; --red-10:#fdeff2; --red-5:#fef7f8;\n    --white:#ffffff;\n    --text-primary:var(--black-100); --text-secondary:var(--black-40); --text-accent:var(--theme-100);\n    --global-line:var(--theme-40); --global-input:var(--theme-5); --global-hover:var(--theme-15);\n    --global-nav:var(--theme-40);\n    --dropshadow-light:rgba(33,113,83,.4); --dropshadow-dark:rgba(0,23,14,.4);\n  }\n  * { box-sizing:border-box; }\n  html, body { height:100%; }\n  body {\n    margin:0; overflow:hidden;\n    font:400 13px/1.3 'Noto Sans JP','Hiragino Sans','Yu Gothic',Meiryo,sans-serif;\n    letter-spacing:.04em; color:var(--text-primary); background:transparent;\n  }\n  /* スクロールバー */\n  ::-webkit-scrollbar { width:8px; height:8px; }\n  ::-webkit-scrollbar-thumb { background:var(--theme-20); border-radius:4px; }\n  ::-webkit-scrollbar-thumb:hover { background:var(--theme-40); }\n  ::-webkit-scrollbar-corner { background:transparent; }\n\n  /* ===== ボタン（ピル型） ===== */\n  button {\n    all:unset; cursor:pointer; display:inline-flex; align-items:center; justify-content:center;\n    height:26px; padding:0 12px; border-radius:100px;\n    font:700 12px/1.3 'Noto Sans JP',sans-serif; letter-spacing:.04em;\n    background:var(--white); color:var(--text-accent);\n    box-shadow:0 1px 4px 0 var(--dropshadow-light);\n    white-space:nowrap;\n  }\n  button:hover { background:var(--global-hover); }\n  button.primary { background:var(--theme-100); color:var(--white); }\n  button.primary:hover { background:var(--theme-90); }\n  button.danger { color:var(--red-100); }\n  button.danger:hover { background:var(--red-15); }\n\n  /* ===== 入力 ===== */\n  select, input[type=\"number\"], input[type=\"date\"], input[type=\"text\"] {\n    background:var(--global-input); border:1px solid transparent; border-radius:8px;\n    padding:3px 8px; font:400 12px/1.3 'Noto Sans JP',sans-serif; color:var(--text-primary);\n    outline:none; height:26px;\n  }\n  select:hover, input:hover { background:var(--global-hover); }\n  select:focus, input:focus { border-color:var(--theme-50); background:var(--global-input); }\n  input.err { border-color:var(--red-100); background:var(--red-10); color:var(--red-110); }\n  input[type=\"checkbox\"] { accent-color:var(--theme-100); cursor:pointer; }\n  input[type=\"file\"] { background:none; height:auto; }\n\n  /* ===== 全体レイアウト（PlanoCycle埋め込み） ===== */\n  #appRoot { display:flex; flex-direction:column; height:100%; width:100%; background:transparent; }\n  /* 配置モード */\n  #mapScroll.placing #mapSvg, #mapScroll.placing .obj rect.body, #mapScroll.placing .handle { cursor:crosshair !important; }\n  button.activeMode { background:var(--theme-30); color:var(--theme-110); }\n\n  #frame { flex:1; display:flex; flex-direction:column; min-width:0; min-height:0; }\n  #frameHeader { display:flex; align-items:center; gap:8px; padding:0 0 10px; flex-wrap:wrap; flex:0 0 auto; }\n  #frameHeader h1 { display:none; } /* タイトルは外側Vueが担当 */\n  #frameHeader label { color:var(--text-secondary); font-size:12px; }\n  #frameHeader select { min-width:150px; height:30px; background:var(--white); }\n  #frameHeader .spacer { flex:1; }\n\n  #main { display:flex; flex:1; min-height:0; padding:0; gap:0; }\n  #mapPane, #rightPane { background:var(--white); border-radius:16px; overflow:hidden; box-shadow:0 1px 4px rgba(33,113,83,.12); }\n  #mapPane { flex:1.1; display:flex; flex-direction:column; min-width:260px; }\n  #splitter { flex:0 0 8px; cursor:col-resize; background:transparent; position:relative; }\n  #splitter::after { content:''; position:absolute; left:3px; top:45%; width:2px; height:10%; min-height:40px; border-radius:2px; background:var(--theme-40); }\n  #splitter:hover::after, #splitter.active::after { background:var(--theme-100); }\n\n  #mapToolbar { display:flex; gap:6px; align-items:center; padding:8px 12px; border-bottom:1px solid var(--theme-20); flex-wrap:wrap; }\n  #mapToolbar .note { color:var(--text-secondary); font-size:11px; }\n  #objEditor { display:none; gap:8px; align-items:center; padding:7px 12px; background:var(--theme-15); border-bottom:1px solid var(--theme-20); flex-wrap:wrap; }\n  #objEditor.show { display:flex; }\n  #objEditor b { color:var(--text-accent); font-size:12px; }\n  #objEditor label { color:var(--text-secondary); font-size:12px; }\n  #objEditor .errmsg { color:var(--red-100); font-weight:700; font-size:12px; }\n  #mapScroll { flex:1; overflow:auto; position:relative; background:var(--theme-5); }\n  #mapEmpty { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; color:var(--text-secondary); text-align:center; line-height:2; }\n  #mapSvg { display:block; background:#fff; }\n  .obj rect.body { fill-opacity:.35; cursor:move; }\n  .obj text { font-weight:700; pointer-events:none; user-select:none; }\n  .handle { fill:#fff; stroke:var(--theme-100); }\n  #zoomPct { color:var(--text-secondary); font-size:11px; }\n\n  #rightPane { flex:1; display:flex; flex-direction:column; min-width:380px; }\n  #rightToolbar { display:flex; gap:8px; align-items:center; padding:8px 12px; border-bottom:1px solid var(--theme-20); flex-wrap:wrap; }\n  #rightToolbar > b { font:700 14px/1.3 'Noto Sans JP',sans-serif; }\n  .chip { display:none; color:var(--text-accent); background:var(--theme-15); padding:3px 10px; border-radius:100px; font-size:11px; }\n  #themeApplyBar { display:none; gap:8px; align-items:center; padding:7px 12px; background:var(--theme-15); border-bottom:1px solid var(--theme-20); flex-wrap:wrap; }\n  #themeApplyBar.show { display:flex; }\n  #themeApplyBar b { color:var(--text-accent); font-size:12px; }\n  /* テーマ選択のコンボボックス（クリックで常に全件、入力で絞り込み） */\n  .combo { position:relative; display:inline-flex; align-items:center; }\n  .combo > input { padding-right:22px; }\n  .combo .comboClear { position:absolute; right:4px; border:0; background:transparent; color:var(--text-secondary);\n    cursor:pointer; font-size:14px; line-height:1; padding:2px 4px; display:none; }\n  .combo.hasValue .comboClear { display:block; }\n  .comboMenu { position:absolute; top:100%; left:0; z-index:60; min-width:100%; max-height:260px; overflow:auto;\n    background:var(--white); border:1px solid var(--global-line); border-radius:8px; margin-top:2px;\n    box-shadow:0 6px 20px rgba(0,0,0,.12); display:none; }\n  .comboMenu.show { display:block; }\n  .comboMenu .opt { padding:6px 10px; font-size:12px; cursor:pointer; white-space:nowrap; }\n  .comboMenu .opt:hover, .comboMenu .opt.active { background:var(--global-hover); }\n  .comboMenu .empty { padding:8px 10px; font-size:12px; color:var(--text-secondary); }\n  #tableWrap { flex:1; overflow:auto; }\n\n  /* ===== テーブル ===== */\n  table.loc { border-collapse:separate; border-spacing:0; width:max-content; min-width:100%; }\n  table.loc th, table.loc td { box-sizing:border-box; border-right:1px solid var(--theme-20); border-bottom:1px solid var(--theme-20); padding:4px 6px; white-space:nowrap; background:var(--white); }\n  table.loc th:first-child, table.loc td:first-child { border-left:none; }\n  table.loc thead th { font:400 11px/1.3 'Noto Sans JP',sans-serif; color:var(--text-secondary); border-top:none; position:sticky; top:0; z-index:2; background:var(--theme-5); }\n  table.loc th.dateCol { background:var(--theme-15); color:var(--text-accent); font-weight:700; cursor:context-menu; min-width:110px; }\n  .fc { position:sticky; z-index:1; }\n  table.loc thead th.fc { z-index:4; }\n  .fc0 { left:0;     width:32px;  min-width:32px;  max-width:32px; }\n  .fc1 { left:32px;  width:112px; min-width:112px; max-width:112px; overflow:hidden; text-overflow:ellipsis; }\n  .fc2 { left:144px; width:40px;  min-width:40px;  max-width:40px; text-align:center; box-shadow:2px 0 4px rgba(33,113,83,.10); }\n  /* 2段セル（テーマ＋什器） */\n  td.themeCell { padding:3px 6px; vertical-align:top; user-select:none; }\n  #mapSvg image { transition:opacity .15s ease; }\n  table.loc th.dateCol { cursor:pointer; }\n  /* 日付列の操作ボタン（右クリックに気づかなくても・タブレットでも操作できるように） */\n  table.loc th.dateCol { position:relative; padding-right:20px; }\n  table.loc th.dateCol .dateMenuBtn { position:absolute; top:2px; right:2px; border:0; background:transparent;\n    color:var(--text-accent); cursor:pointer; font-size:13px; line-height:1; padding:2px 4px; border-radius:4px;\n    opacity:.45; }\n  table.loc th.dateCol:hover .dateMenuBtn { opacity:1; }\n  table.loc th.dateCol .dateMenuBtn:hover { background:var(--theme-30); }\n  .cellTheme { font-size:12px; line-height:1.35; }\n  /* 分割セル（期間限定で表／裏に割る） */\n  td.themeCell.splitCell { padding:2px; }\n  .splitWrap { display:flex; flex-direction:column; gap:2px; }\n  .cellPart { flex:1; min-width:0; border:1px dashed var(--theme-40); border-radius:5px;\n    padding:2px 4px; cursor:pointer; background:var(--white); }\n  .cellPart.selectedCell { background:var(--theme-30); border-style:solid; border-color:var(--theme-100); }\n  .cellPart .partNo { display:inline-block; font-size:9px; color:var(--text-accent);\n    background:var(--theme-15); border-radius:3px; padding:0 3px; margin-right:3px; }\n  .cellPart .partTheme { font-size:11px; line-height:1.3; }\n  .cellTheme .empty { color:var(--black-30); }\n  .cellFix { font-size:10px; color:var(--text-secondary); line-height:1.3; margin-top:1px; }\n  #themeApplyBar .sep { width:1px; height:18px; background:var(--theme-40); }\n  #themeApplyBar label { color:var(--text-secondary); font-size:11px; }\n  table.loc tbody tr[data-obj] { cursor:pointer; }\n  table.loc tbody tr[data-obj]:hover td { background:var(--global-hover); }\n  table.loc tbody tr.hlRow td { background:var(--theme-20); }\n  table.loc tbody tr.hlRow td.fc1 { border-left:3px solid var(--theme-100); }\n  td.themeCell { cursor:pointer; min-width:110px; max-width:180px; overflow:hidden; text-overflow:ellipsis; }\n  td.themeCell.selectedCell { outline:2px solid var(--theme-100); outline-offset:-2px; background:var(--theme-20) !important; }\n  td.themeCell.dragOver { background:var(--theme-30) !important; }\n  .catBadge { display:inline-block; width:10px; height:10px; border-radius:3px; margin-right:4px; vertical-align:middle; }\n\n  /* ===== モーダル ===== */\n  .modalBack { display:none; position:fixed; inset:0; background:rgba(47,65,54,.25); z-index:50; align-items:center; justify-content:center; }\n  .modalBack.show { display:flex; }\n  .modal { background:var(--theme-10); border-radius:24px; padding:24px 28px; min-width:360px; max-width:540px; box-shadow:0 2px 12px 0 var(--dropshadow-dark); }\n  .modal h3 { margin:0 0 14px; font:700 16px/1.3 'Noto Sans JP',sans-serif; }\n  .modal .btns { display:flex; justify-content:flex-end; gap:10px; margin-top:18px; }\n  .modal .btns button { height:32px; padding:0 18px; font-size:13px; }\n  .modal .hint { color:var(--text-secondary); font-size:11px; margin-top:8px; line-height:1.7; }\n  .modal input[type=\"date\"] { background:var(--white); height:34px; font-size:14px; }\n  #themeListView { max-height:200px; overflow:auto; background:var(--white); border-radius:8px; padding:8px 12px; margin-top:10px; line-height:1.9; }\n\n  /* ===== コンテキストメニュー・トースト ===== */\n  #ctxMenu { display:none; position:fixed; z-index:60; background:var(--white); border-radius:8px; box-shadow:0 2px 12px 0 var(--dropshadow-dark); min-width:180px; padding:8px; }\n  #ctxMenu div { padding:8px 12px; cursor:pointer; border-radius:8px; }\n  #ctxMenu div:hover { background:var(--global-hover); }\n  #ctxMenu div.danger { color:var(--red-100); }\n  #ctxMenu div.danger:hover { background:var(--red-15); }\n  #toast { position:fixed; bottom:20px; left:50%; transform:translateX(-50%); background:var(--black-100); color:#fff; padding:9px 20px; border-radius:100px; opacity:0; transition:opacity .3s; z-index:70; pointer-events:none; font-size:12px; }\n  #toast.show { opacity:.96; }\n  /* embed tweaks */\n  html, body { width:100%; height:100%; overflow:hidden; background:transparent; }\n  #headerActions { display:flex; gap:6px; align-items:center; flex-wrap:wrap; }\n</style>\n</head>\n<body>\n\n<div id=\"appRoot\">\n\n<div id=\"frame\">\n<div id=\"frameHeader\">\n  <h1>売場ロケーション</h1>\n  <label>店舗</label>\n  <select id=\"storeSelect\"></select>\n  <button id=\"btnAddStore\">＋店舗追加</button>\n  <button id=\"btnRenameStore\">名称変更</button>\n  <button id=\"btnDeleteStore\" class=\"danger\">店舗削除</button>\n  <div class=\"spacer\"></div>\n  <div id=\"headerActions\">\n    <button id=\"btnSettings\" title=\"テーマ一覧\">テーマ一覧</button>\n    <button id=\"btnExportXlsx\" class=\"primary\" style=\"height:32px; padding:0 18px; font-size:13px;\">Excelダウンロード</button>\n    <button id=\"btnMoreActions\" title=\"その他の操作（バックアップ）\">⋯</button>\n  </div>\n</div>\n\n<div id=\"main\">\n  <div id=\"mapPane\">\n    <div id=\"mapToolbar\">\n      <button id=\"btnPickImage\">マップ画像を選択</button>\n      <span class=\"note\">（キャプチャを Ctrl+V で貼り付け可 / 範囲ドラッグ・Shift+クリックで複数選択）</span>\n      <button id=\"btnAddObj\" class=\"primary\">＋ オブジェクト追加</button>\n      <span style=\"margin-left:auto; display:flex; gap:4px; align-items:center;\">\n        <button id=\"btnZoomOut\" title=\"縮小 (Ctrl+ホイール)\">−</button>\n        <span id=\"zoomPct\" style=\"min-width:44px; text-align:center;\">100%</span>\n        <button id=\"btnZoomIn\" title=\"拡大 (Ctrl+ホイール)\">＋</button>\n        <button id=\"btnZoomFit\">全体</button>\n        <button id=\"btnMapDim\" title=\"マップ画像を薄くしてオブジェクトを見やすくします（自動 / 常に薄く / 通常 を切り替え）\">背景 自動</button>\n      </span>\n    </div>\n    <div id=\"objEditor\">\n      <b id=\"selInfo\">選択中:</b>\n      <span id=\"singleEdit\" style=\"display:flex; gap:6px; align-items:center;\">\n        <label>カテゴリ</label>\n        <select id=\"objCategory\"><option value=\"\">-- 選択 --</option></select>\n        <label>番号</label>\n        <input type=\"number\" id=\"objNumber\" min=\"1\" step=\"1\" style=\"width:60px\" list=\"numList\">\n        <datalist id=\"numList\"></datalist>\n        <span class=\"errmsg\" id=\"objErr\"></span>\n      </span>\n      <span id=\"multiEdit\" style=\"display:none; gap:6px; align-items:center;\">\n        <label>対象日</label>\n        <select id=\"multiDateSel\"></select>\n        <span id=\"multiDateHint\" style=\"display:none; color:var(--text-secondary); font-size:11px;\">（先に「開始日時点の売場を設定」で日付を追加してください）</span>\n        <span style=\"color:var(--text-secondary); font-size:11px;\">→ 右のテーマ適用バーで一括設定できます</span>\n      </span>\n      <button id=\"btnDupObj\">⧉ 複製 (Ctrl+D)</button>\n      <button id=\"btnDelObj\" class=\"danger\">削除</button>\n    </div>\n    <div id=\"mapScroll\">\n      <div id=\"mapEmpty\">マップ画像がありません<br>「マップ画像を選択」またはキャプチャを貼り付け（Ctrl+V）してください</div>\n      <svg id=\"mapSvg\" xmlns=\"http://www.w3.org/2000/svg\"></svg>\n    </div>\n  </div>\n\n  <div id=\"splitter\" title=\"ドラッグで幅を調整\"></div>\n\n  <div id=\"rightPane\">\n    <div id=\"rightToolbar\">\n      <b>ロケーション一覧</b>\n      <label style=\"color:var(--text-secondary); font-size:11px;\">カテゴリ</label>\n      <select id=\"catFilter\"><option value=\"\">すべて</option></select>\n      <span id=\"fixCopyInfo\" class=\"chip\"></span>\n      <div class=\"spacer\" style=\"flex:1\"></div>\n      <button id=\"btnAddDate\" class=\"primary\">＋ 開始日時点の売場を設定</button>\n    </div>\n    <div id=\"themeApplyBar\">\n      <b id=\"selCount\"></b>\n      <label>テーマ</label>\n      <div class=\"combo\" id=\"themeCombo\">\n        <input id=\"themeSelect\" type=\"text\" autocomplete=\"off\" placeholder=\"キーワードで検索\" style=\"width:200px\">\n        <button type=\"button\" id=\"themeComboClear\" class=\"comboClear\" title=\"クリア\" tabindex=\"-1\">×</button>\n        <div class=\"comboMenu\" id=\"themeMenu\" role=\"listbox\"></div>\n      </div>\n      <button id=\"btnApplyTheme\" class=\"primary\">テーマ適用</button>\n      <span class=\"sep\"></span>\n      <label>什器</label>\n      <select id=\"fixTypeSel\"><option value=\"\">--</option><option>パレット</option><option>ベースカート</option><option>ゴンドラ</option></select>\n      <span id=\"fixDetailBox\"></span>\n      <button id=\"btnApplyFix\" class=\"primary\">什器適用</button>\n      <span class=\"sep\"></span>\n      <span class=\"sep\"></span>\n      <button id=\"btnSplitCell\" title=\"選択したセルを2つに割って、表と裏で別のテーマ・什器を設定できるようにします\">⬍ 分割</button>\n      <button id=\"btnMergeCells\" title=\"分割を解除して1つに戻します\">⤫ 分割解除</button>\n      <span class=\"sep\"></span>\n      <button id=\"btnClearCells\" class=\"danger\">消去</button>\n      <button id=\"btnDeselect\">選択解除</button>\n    </div>\n    <div id=\"tableWrap\"><table class=\"loc\" id=\"locTable\"><thead></thead><tbody></tbody></table></div>\n  </div>\n</div>\n\n</div>\x3c!-- /frame --\x3e\n</div>\x3c!-- /appRoot --\x3e\n\n\x3c!-- 日付選択モーダル --\x3e\n<div class=\"modalBack\" id=\"dateModal\">\n  <div class=\"modal\">\n    <h3 id=\"dateModalTitle\">開始日を選択</h3>\n    <input type=\"date\" id=\"dateInput\" style=\"font-size:14px; padding:6px;\">\n    <div class=\"hint\" id=\"dateHint\"></div>\n    <div class=\"btns\">\n      <button id=\"dateCancel\">キャンセル</button>\n      <button id=\"dateOk\" class=\"primary\">確定</button>\n    </div>\n  </div>\n</div>\n\n\x3c!-- テーマ一覧モーダル（MDリスト連携） --\x3e\n<div class=\"modalBack\" id=\"settingsModal\">\n  <div class=\"modal\" style=\"min-width:420px; max-width:640px;\">\n    <h3>テーマ一覧（MDリスト連携）</h3>\n    <div class=\"hint\">テーマはMDリストのテーママスタを利用します。ロケーションのカテゴリに応じて選択できるテーマが絞り込みます（主通路ミッド＝全テーマ／各ディビジョン＝該当ディビジョンのみ）。</div>\n    <div id=\"themeListView\"></div>\n    <div class=\"btns\">\n      <button id=\"settingsClose\" class=\"primary\">閉じる</button>\n    </div>\n  </div>\n</div>\n\n<div id=\"ctxMenu\"></div>\n<div id=\"toast\"></div>\n<input type=\"file\" id=\"imageFile\" accept=\"image/*\" style=\"display:none\">\n<input type=\"file\" id=\"jsonFile\" accept=\".json\" style=\"display:none\">\n\n<script>\n'use strict';\n/* __INJECT_MD_THEMES__ */\n/* __INJECT_MVP_API__ */\n/* ================= 定数 ================= */\nconst CATEGORIES = ['主通路ミッド','グロエンド','グロミッド','菓子エンド','菓子ミッド','飲料エンド','飲料ミッド','酒エンド','酒ミッド'];\nconst CAT_SHORT = {'主通路ミッド':'主通','グロエンド':'グE','グロミッド':'グM','菓子エンド':'菓E','菓子ミッド':'菓M','飲料エンド':'飲E','飲料ミッド':'飲M','酒エンド':'酒E','酒ミッド':'酒M'};\n/** ロケーションカテゴリ → MDテーマのディビジョン（null = 全テーマ） */\nconst CAT_DIVISION = {\n  '主通路ミッド': null,\n  'グロエンド': 'グロサリー',\n  'グロミッド': 'グロサリー',\n  '菓子エンド': '菓子',\n  '菓子ミッド': '菓子',\n  '飲料エンド': '飲料',\n  '飲料ミッド': '飲料',\n  '酒エンド': '酒',\n  '酒ミッド': '酒'\n};\n/**\n * MDテーママスタに依存しない常設選択肢。\n * 在庫残・値下げ展開など、特定テーマを当てずフリースペースとして使うときに選ぶ。\n * 「消去」(未設定の −) とは区別して意図的なフリーを残す。\n */\nconst FREE_FLOOR_THEME = 'フリー売場';\n/** ディビジョンごとの表示色（マップ上のオブジェクト・右リストのカテゴリバッジで共通使用） */\nconst DIVISION_COLORS = { 'グロサリー':'#f472b6', '菓子':'#facc15', '酒':'#38bdf8', '飲料':'#2563eb' };\nconst CAT_COLORS = {};\nfor(const cat of CATEGORIES){\n  const div = CAT_DIVISION[cat];\n  CAT_COLORS[cat] = (div && DIVISION_COLORS[div]) || '#6366f1'; // 主通路ミッド等（ディビジョン無し）は既定色\n}\nconst FIXTURES = ['パレット','ベースカート','ゴンドラ'];\n/** 棚構造を持つ什器。旧データは「エンド」で保存されているため読み込み時に正規化する */\nconst SHELF_FIXTURE_TYPE = 'ゴンドラ';\nconst LEGACY_SHELF_FIXTURE_TYPE = 'エンド';\nfunction normalizeFixtureType(type){\n  return type === LEGACY_SHELF_FIXTURE_TYPE ? SHELF_FIXTURE_TYPE : type;\n}\nfunction isShelfFixtureType(type){\n  return type === SHELF_FIXTURE_TYPE || type === LEGACY_SHELF_FIXTURE_TYPE;\n}\nfunction normalizeFixture(f){\n  if(!f || !f.type) return f;\n  const type = normalizeFixtureType(f.type);\n  return type === f.type ? f : { ...f, type };\n}\nconst LS_KEY = 'baiba-location-tool-v2';\nconst $ = id => document.getElementById(id);\n\nfunction mvpApiConfig(){\n  const c = window.__MVP_API__;\n  return c && c.enabled && c.url && c.key ? c : null;\n}\n/** Supabase(PostgREST) への直fetch。ポップアップ接続は不要（CORSが開いている） */\nasync function pgFetch(path, opts){\n  const c = mvpApiConfig();\n  if(!c) throw new Error('Supabase未設定');\n  opts = opts || {};\n  const headers = Object.assign({\n    apikey: c.key,\n    Authorization: 'Bearer ' + c.key,\n    'Content-Type': 'application/json'\n  }, opts.headers || {});\n  const res = await fetch(c.url.replace(/\\/$/, '') + '/rest/v1/' + path, Object.assign({}, opts, { headers }));\n  const text = await res.text();\n  let body = null;\n  if(text){\n    try { body = JSON.parse(text); } catch(e){ throw new Error('API応答がJSONではありません（HTTP ' + res.status + '）: ' + text.slice(0,200)); }\n  }\n  if(!res.ok) throw new Error((body && (body.message || body.error)) || ('APIエラー（HTTP ' + res.status + '）'));\n  return body;\n}\nasync function mvpGetLocation(storeId){\n  const q = 'store_id=eq.' + encodeURIComponent(storeId);\n  const [storeRows, objects, dates, assignmentRows] = await Promise.all([\n    pgFetch('stores?' + q + '&select=*'),\n    pgFetch('store_objects?' + q + '&select=*'),\n    pgFetch('store_dates?' + q + '&select=date&order=sort'),\n    pgFetch('assignments?' + q + '&select=*')\n  ]);\n  const store = storeRows[0];\n  if(!store) throw new Error('store not found');\n  const assignments = {};\n  assignmentRows.forEach(a => {\n    assignments[a.date] = assignments[a.date] || {};\n    assignments[a.date][a.object_id] = {\n      theme: a.theme_key || '',\n      fixture: a.fixture_type ? normalizeFixture({\n        type: a.fixture_type, count: a.fixture_count, shaku: a.fixture_shaku, heightMm: a.fixture_height_mm\n      }) : null\n    };\n  });\n  return {\n    store: {\n      id: store.store_id, name: store.name, mapFileId: store.map_file_id,\n      mapUrl: store.map_url, mapW: store.map_w, mapH: store.map_h\n    },\n    objects: objects.map(o => ({ id: o.object_id, category: o.category, number: o.number, x: o.x, y: o.y, w: o.w, h: o.h })),\n    dates: dates.map(d => d.date),\n    assignments\n  };\n}\nasync function mvpSaveLocation(payload, user){\n  return pgFetch('rpc/save_location', { method:'POST', body: JSON.stringify({ payload: payload, p_user: user }) });\n}\n/** Supabase Storage（mapsバケット、public）へ画像アップロード。Driveのような共有ポリシー制限を受けない */\nasync function mvpUploadMapImage(storeId, blob, fileName){\n  const c = mvpApiConfig();\n  if(!c) throw new Error('Supabase未設定');\n  // Supabase Storageのキーは店舗名等の非ASCII文字を含むと InvalidKey で拒否されるため、拡張子のみ引き継ぐ\n  const extMatch = /\\.([a-zA-Z0-9]+)$/.exec(fileName || '');\n  const ext = (extMatch && extMatch[1]) || (blob.type && blob.type.split('/')[1]) || 'jpg';\n  const safeExt = ext.replace(/[^a-zA-Z0-9]/g, '') || 'jpg';\n  const path = storeId + '/' + Date.now() + '.' + safeExt;\n  const encodedPath = path.split('/').map(encodeURIComponent).join('/');\n  const base = c.url.replace(/\\/$/, '');\n  const res = await fetch(base + '/storage/v1/object/maps/' + encodedPath, {\n    method: 'POST',\n    headers: {\n      apikey: c.key,\n      Authorization: 'Bearer ' + c.key,\n      'Content-Type': blob.type || 'application/octet-stream',\n      'x-upsert': 'true'\n    },\n    body: blob\n  });\n  if(!res.ok){\n    const t = await res.text();\n    throw new Error('画像アップロード失敗（HTTP ' + res.status + '）: ' + t.slice(0,200));\n  }\n  return { mapUrl: base + '/storage/v1/object/public/maps/' + encodedPath, mapFileId: path };\n}\nfunction locationToStore(loc){\n  const s = loc.store || {};\n  return migrateStore({\n    id: String(s.id || s.storeId || uid('st')),\n    name: String(s.name || s.id || '店舗'),\n    // Supabase Storageのpublic URLなので直接<image href>で表示できる\n    mapImage: s.mapUrl || null,\n    mapFileId: s.mapFileId || '',\n    mapUrl: s.mapUrl || '',\n    mapW: Number(s.mapW || 1200) || 1200,\n    mapH: Number(s.mapH || 800) || 800,\n    objects: (loc.objects || []).map(o => ({\n      id: String(o.id),\n      category: o.category || '',\n      number: o.number == null || o.number === '' ? null : Number(o.number),\n      x: Number(o.x || 0), y: Number(o.y || 0), w: Number(o.w || 0), h: Number(o.h || 0)\n    })),\n    dates: [...(loc.dates || [])],\n    assignments: decodeAssignments(loc.assignments || {})\n  });\n}\nfunction storeToLocationPayload(st){\n  return {\n    store: {\n      id: st.id,\n      name: st.name,\n      mapFileId: st.mapFileId || '',\n      mapUrl: st.mapUrl || (typeof st.mapImage === 'string' && /^https?:/.test(st.mapImage) ? st.mapImage : ''),\n      mapW: st.mapW || 0,\n      mapH: st.mapH || 0\n    },\n    objects: (st.objects || []).map(o => ({\n      id: o.id, category: o.category || '', number: o.number == null ? null : o.number,\n      x: o.x || 0, y: o.y || 0, w: o.w || 0, h: o.h || 0\n    })),\n    dates: [...(st.dates || [])],\n    assignments: encodeAssignments(st.assignments || {})\n  };\n}\nlet remoteSaveTimer = null;\nlet remoteSaving = false;\nasync function saveCurrentStoreRemote(){\n  const c = mvpApiConfig();\n  if(!c || remoteSaving) return;\n  const st = curStore();\n  if(!st || !st.id) return;\n  remoteSaving = true;\n  try {\n    await mvpSaveLocation(storeToLocationPayload(st), c.user || '');\n    toast('Supabaseへ保存しました');\n  } catch(err){\n    console.warn(err);\n    toast('Supabase保存に失敗（ローカルには保存済み）: ' + (err.message || err));\n  } finally {\n    remoteSaving = false;\n  }\n}\nasync function loadFromRemote(){\n  const storesMeta = await pgFetch('stores?select=store_id,name,map_file_id,map_url,map_w,map_h');\n  if(!storesMeta.length) return null;\n  const stores = [];\n  for(const meta of storesMeta){\n    try {\n      const loc = await mvpGetLocation(String(meta.store_id));\n      stores.push(locationToStore(loc));\n    } catch(err){\n      stores.push(migrateStore({\n        id: String(meta.store_id),\n        name: meta.name || meta.store_id,\n        mapImage: meta.map_url || null,\n        mapFileId: meta.map_file_id || '',\n        mapUrl: meta.map_url || '',\n        mapW: Number(meta.map_w || 1200) || 1200,\n        mapH: Number(meta.map_h || 800) || 800,\n        objects: [], dates: [], assignments: {}\n      }));\n    }\n  }\n  return { version:1, themeList:[], stores, currentStoreId: stores[0].id };\n}\n\n/** MDリストから注入されたテーマ一覧 {id,name,division,startDate,endDate}[] */\nfunction getMdThemes(){\n  return Array.isArray(window.__MD_THEMES__) ? window.__MD_THEMES__ : [];\n}\n/**\n * 日付付きユニーク名 → テーマ本体名\n * 例: 「カップ麺【BU】（2026/05/01〜05/10・グロサリー）」→「カップ麺【BU】」\n */\nfunction themeBaseName(name){\n  const s = String(name == null ? '' : name).trim();\n  if(!s) return '';\n  return s\n    .replace(/（\\d{4}\\/\\d{2}\\/\\d{2}〜[^）]*）$/u, '')\n    .replace(/（\\d{4}\\/\\d{2}・[^）]*）$/u, '')\n    .trim() || s;\n}\n/** ディビジョン絞り込み＋日付なしでユニーク化したテーマ一覧 */\nfunction uniqueThemesByBase(list){\n  const seen = new Set();\n  const out = [];\n  for(const t of list){\n    const base = themeBaseName(t.name);\n    if(!base || seen.has(base)) continue;\n    seen.add(base);\n    out.push({ id: t.id, name: base, division: t.division || '' });\n  }\n  out.sort((a, b) => a.name.localeCompare(b.name, 'ja'));\n  return out;\n}\n/** カテゴリに選べるテーマ（日付なし・重複なし） */\nfunction themesForCategory(category){\n  const all = getMdThemes();\n  let list = all;\n  if(category && (category in CAT_DIVISION)){\n    const div = CAT_DIVISION[category];\n    if(div != null) list = all.filter(t => t.division === div);\n  }\n  return uniqueThemesByBase(list);\n}\n/** 選択セル群に共通して適用可能なテーマ（交差・日付なし） */\nfunction themesForSelection(){\n  const st = curStore();\n  const cats = new Set();\n  for(const key of selectedCells){\n    const objId = key.split('|')[0];\n    const o = st.objects.find(x => x.id === objId);\n    cats.add(o && o.category ? o.category : '');\n  }\n  let list;\n  if(!cats.size){\n    list = uniqueThemesByBase(getMdThemes());\n  } else {\n    let allowed = null;\n    for(const cat of cats){\n      const names = new Set(themesForCategory(cat).map(t => t.name));\n      allowed = allowed ? new Set([...allowed].filter(n => names.has(n))) : names;\n    }\n    list = uniqueThemesByBase(getMdThemes()).filter(t => allowed.has(t.name));\n  }\n  // フリー売場はカテゴリ・ディビジョンを問わず常に先頭へ\n  const withoutFree = list.filter(t => t.name !== FREE_FLOOR_THEME);\n  return [{ id: '__free_floor__', name: FREE_FLOOR_THEME, division: '' }, ...withoutFree];\n}\nfunction divisionLabelForCategory(category){\n  if(!category) return '（カテゴリ未設定＝全テーマ）';\n  if(!(category in CAT_DIVISION)) return category;\n  const div = CAT_DIVISION[category];\n  return div == null ? `${category}（全テーマ）` : `${category}（${div}）`;\n}\n\n/* ================= 状態 ================= */\nlet state = null;\nlet selectedObjIds = new Set();  // マップ上の複数選択\nlet selectedCells = new Set();   // \"objId|date\"\nlet drag = null;\nlet zoom = 1;\nfunction clamp(v, lo, hi){ return Math.max(lo, Math.min(hi, v)); }\n\nfunction uid(p){ return p + '-' + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }\nfunction newStore(name){ return { id:uid('st'), name, mapImage:null, mapW:1200, mapH:800, objects:[], dates:[], assignments:{} }; }\nfunction defaultState(){ const st = newStore('店舗1'); return { version:1, themeList:[], stores:[st], currentStoreId:st.id }; }\nfunction curStore(){ return state.stores.find(s=>s.id===state.currentStoreId) || state.stores[0]; }\nfunction getAsg(store, date){ if(!store.assignments[date]) store.assignments[date] = {}; return store.assignments[date]; }\n\n/* ================= 永続化 ================= */\nlet saveTimer = null;\nfunction saveState(){\n  clearTimeout(saveTimer);\n  saveTimer = setTimeout(()=>{\n    try { localStorage.setItem(LS_KEY, JSON.stringify(state)); }\n    catch(e){ toast('自動保存に失敗しました（容量超過の可能性）。JSON保存をご利用ください'); }\n    if(mvpApiConfig()){\n      clearTimeout(remoteSaveTimer);\n      remoteSaveTimer = setTimeout(() => { void saveCurrentStoreRemote(); }, 1500);\n    }\n  }, 400);\n}\nfunction loadState(){\n  try { const raw = localStorage.getItem(LS_KEY); if(raw) return JSON.parse(raw); } catch(e){}\n  return null;\n}\n\n/* ================= ユーティリティ ================= */\nfunction toast(msg){\n  const t = $('toast'); t.textContent = msg; t.classList.add('show');\n  clearTimeout(t._tm); t._tm = setTimeout(()=>t.classList.remove('show'), 2600);\n}\nfunction addDays(iso, n){\n  const d = new Date(iso + 'T00:00:00Z');\n  d.setUTCDate(d.getUTCDate() + n);\n  return d.toISOString().slice(0,10);\n}\nfunction fmtDate(iso){ const [y,m,d] = iso.split('-'); return `${+m}/${+d}〜`; }\nfunction esc(s){ return String(s==null?'':s).replace(/[&<>\"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])); }\nfunction dupError(store, obj){\n  return !!(obj.category && obj.number && store.objects.some(o => o.id!==obj.id && o.category===obj.category && o.number===obj.number));\n}\nfunction rowObjects(store){\n  return store.objects\n    .filter(o => o.category && o.number && !dupError(store, o))\n    .sort((a,b) => (CATEGORIES.indexOf(a.category)-CATEGORIES.indexOf(b.category)) || (a.number-b.number));\n}\nlet catFilter = '';\nfunction visibleObjects(store){\n  const objs = rowObjects(store);\n  return catFilter ? objs.filter(o => o.category === catFilter) : objs;\n}\n\n/* ================= マップ描画 ================= */\nconst svg = $('mapSvg');\nfunction renderMap(){\n  const st = curStore();\n  if(!st.mapImage){\n    $('mapEmpty').style.display = 'flex';\n    svg.style.display = 'none';\n    return;\n  }\n  $('mapEmpty').style.display = 'none';\n  svg.style.display = 'block';\n  svg.setAttribute('viewBox', `0 0 ${st.mapW} ${st.mapH}`);\n  svg.style.width = (zoom*100) + '%';\n  svg.innerHTML = `<image id=\"mapBg\" href=\"${st.mapImage}\" x=\"0\" y=\"0\" width=\"${st.mapW}\" height=\"${st.mapH}\"/><g id=\"objLayer\"></g>`;\n  renderMapObjects();\n}\n/* ===== マップ画像の濃さ =====\n   画像が濃いとオブジェクトが埋もれて見えないため、薄くできるようにする。\n   'auto' … オブジェクトを選択している間だけ薄くする（既定）\n   'on'   … 常に薄くする（配置作業中に便利）\n   'off'  … 薄くしない\n   表示上の好みなので state（Supabase同期対象）ではなく端末側に保存する。 */\nconst MAP_DIM_KEY = 'baibaLoc.mapDim';\nconst MAP_DIM_OPACITY = 0.35;\nconst MAP_DIM_LABEL = { auto:'背景 自動', on:'背景 薄く', off:'背景 通常' };\nlet mapDimMode = (() => {\n  try { const v = localStorage.getItem(MAP_DIM_KEY); if(v && MAP_DIM_LABEL[v]) return v; } catch(e){}\n  return 'auto';\n})();\nfunction applyMapDim(){\n  const img = svg.querySelector('#mapBg');\n  if(img){\n    const dim = mapDimMode === 'on' || (mapDimMode === 'auto' && selectedObjIds.size > 0);\n    img.style.opacity = dim ? MAP_DIM_OPACITY : 1;\n  }\n  const btn = $('btnMapDim');\n  if(btn) btn.textContent = MAP_DIM_LABEL[mapDimMode];\n}\n$('btnMapDim').onclick = () => {\n  const order = ['auto', 'on', 'off'];\n  mapDimMode = order[(order.indexOf(mapDimMode) + 1) % order.length];\n  try { localStorage.setItem(MAP_DIM_KEY, mapDimMode); } catch(e){}\n  applyMapDim();\n  toast({ auto:'選択中のオブジェクトがあるときだけ背景を薄くします',\n          on:'背景を常に薄くします', off:'背景を薄くしません' }[mapDimMode]);\n};\napplyMapDim();   // 保存済みの設定をボタン表示に反映（マップ未読込でもラベルを合わせる）\nfunction renderMapObjects(){\n  const st = curStore();\n  const layer = svg.querySelector('#objLayer');\n  if(!layer) return;\n  // ズームしても画面上の見た目サイズが一定になるよう、zoomで割る\n  const hsBase = Math.max(8, Math.min(20, st.mapW/90));\n  const hs = hsBase / zoom;\n  const fs = Math.max(10, hsBase * 1.1) / zoom;\n  const sw = 2 / zoom;\n  let html = '';\n  for(const o of st.objects){\n    const col = CAT_COLORS[o.category] || '#64748b';\n    const sel = selectedObjIds.has(o.id);\n    const label = o.category ? `${CAT_SHORT[o.category]}-${o.number||'?'}` : '未設定';\n    const dash = sel ? ` stroke-dasharray=\"${5/zoom} ${3/zoom}\"` : '';\n    html += `<g class=\"obj${sel?' selected':''}\" data-id=\"${o.id}\">\n      <rect class=\"body\" x=\"${o.x}\" y=\"${o.y}\" width=\"${o.w}\" height=\"${o.h}\" fill=\"${col}\" stroke=\"${col}\" stroke-width=\"${sel?sw*1.3:sw}\"${dash}/>\n      <text x=\"${o.x+o.w/2}\" y=\"${o.y+o.h/2}\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#111\" font-size=\"${fs}\">${esc(label)}</text>`;\n    if(sel && selectedObjIds.size === 1){\n      const pts = handlePoints(o);\n      for(const [hx,hy,name,cur] of pts){\n        html += `<rect class=\"handle\" data-id=\"${o.id}\" data-handle=\"${name}\" x=\"${hx-hs/2}\" y=\"${hy-hs/2}\" width=\"${hs}\" height=\"${hs}\" stroke-width=\"${1.5/zoom}\" style=\"cursor:${cur}\"/>`;\n      }\n    }\n    html += `</g>`;\n  }\n  layer.innerHTML = html;\n  applyMapDim();   // 選択状態に応じて背景の濃さを反映\n}\nfunction handlePoints(o){\n  const {x,y,w,h} = o;\n  return [\n    [x, y, 'nw', 'nwse-resize'], [x+w/2, y, 'n', 'ns-resize'], [x+w, y, 'ne', 'nesw-resize'],\n    [x+w, y+h/2, 'e', 'ew-resize'], [x+w, y+h, 'se', 'nwse-resize'], [x+w/2, y+h, 's', 'ns-resize'],\n    [x, y+h, 'sw', 'nesw-resize'], [x, y+h/2, 'w', 'ew-resize']\n  ];\n}\nfunction svgPoint(evt){\n  const pt = svg.createSVGPoint();\n  pt.x = evt.clientX; pt.y = evt.clientY;\n  return pt.matrixTransform(svg.getScreenCTM().inverse());\n}\n\n/* ===== マップ操作（移動・リサイズ・範囲選択） ===== */\nsvg.addEventListener('pointerdown', e => {\n  if(e.button !== 0) return;\n  if(placeMode){\n    drag = { mode:'place', start:svgPoint(e) };\n    svg.setPointerCapture(e.pointerId);\n    e.preventDefault();\n    return;\n  }\n  const handle = e.target.closest('.handle');\n  const body = e.target.closest('.obj');\n  const st = curStore();\n  if(handle){\n    const o = st.objects.find(x => x.id === handle.dataset.id);\n    drag = { mode:'resize', id:o.id, handle:handle.dataset.handle, start:svgPoint(e), orig:{...o} };\n  } else if(body){\n    const id = body.dataset.id;\n    if(e.shiftKey){\n      selectedObjIds.has(id) ? selectedObjIds.delete(id) : selectedObjIds.add(id);\n      renderMapObjects(); updateObjEditor();\n      return;\n    }\n    if(!selectedObjIds.has(id)){\n      selectedObjIds = new Set([id]);\n      renderMapObjects(); updateObjEditor();\n    }\n    const origs = {};\n    for(const oid of selectedObjIds){\n      const o = st.objects.find(x => x.id === oid);\n      if(o) origs[oid] = { x:o.x, y:o.y, w:o.w, h:o.h };\n    }\n    drag = { mode:'move', ids:Object.keys(origs), start:svgPoint(e), origs };\n  } else {\n    drag = { mode:'band', start:svgPoint(e), moved:false };\n  }\n  svg.setPointerCapture(e.pointerId);\n  e.preventDefault();\n});\nsvg.addEventListener('pointermove', e => {\n  if(!drag) return;\n  const st = curStore();\n  const p = svgPoint(e);\n  const dx = p.x - drag.start.x, dy = p.y - drag.start.y;\n  if(drag.mode === 'band' || drag.mode === 'place'){\n    if(Math.abs(dx) + Math.abs(dy) > 3) drag.moved = true;\n    updateBandRect(drag.start, p);\n    return;\n  }\n  if(drag.mode === 'move'){\n    let dxLo = -Infinity, dxHi = Infinity, dyLo = -Infinity, dyHi = Infinity;\n    for(const id of drag.ids){\n      const g = drag.origs[id];\n      dxLo = Math.max(dxLo, -g.x); dxHi = Math.min(dxHi, st.mapW - g.w - g.x);\n      dyLo = Math.max(dyLo, -g.y); dyHi = Math.min(dyHi, st.mapH - g.h - g.y);\n    }\n    const cdx = clamp(dx, dxLo, dxHi), cdy = clamp(dy, dyLo, dyHi);\n    for(const id of drag.ids){\n      const o = st.objects.find(x => x.id === id);\n      const g = drag.origs[id];\n      if(o){ o.x = g.x + cdx; o.y = g.y + cdy; }\n    }\n    renderMapObjects();\n    return;\n  }\n  // resize\n  const o = st.objects.find(x => x.id === drag.id);\n  if(!o){ drag = null; return; }\n  const MIN = objMinSize(st);\n  const g = drag.orig;\n  let {x,y,w,h} = g;\n  const hd = drag.handle;\n  if(hd.includes('e')) w = g.w + dx;\n  if(hd.includes('s')) h = g.h + dy;\n  if(hd.includes('w')){ x = g.x + dx; w = g.w - dx; }\n  if(hd.includes('n')){ y = g.y + dy; h = g.h - dy; }\n  if(w < MIN){ if(hd.includes('w')) x -= (MIN - w); w = MIN; }\n  if(h < MIN){ if(hd.includes('n')) y -= (MIN - h); h = MIN; }\n  o.x = Math.max(0, x); o.y = Math.max(0, y);\n  o.w = Math.min(w, st.mapW - o.x); o.h = Math.min(h, st.mapH - o.y);\n  renderMapObjects();\n});\nsvg.addEventListener('pointerup', e => {\n  if(!drag) return;\n  if(drag.mode === 'place'){\n    removeBandRect();\n    placeObjectAt(drag.start, svgPoint(e));\n    setPlaceMode(false);\n    drag = null;\n    return;\n  }\n  if(drag.mode === 'band'){\n    removeBandRect();\n    if(drag.moved){\n      const p = svgPoint(e);\n      const x1 = Math.min(drag.start.x, p.x), x2 = Math.max(drag.start.x, p.x);\n      const y1 = Math.min(drag.start.y, p.y), y2 = Math.max(drag.start.y, p.y);\n      const st = curStore();\n      selectedObjIds = new Set(st.objects.filter(o => o.x < x2 && o.x + o.w > x1 && o.y < y2 && o.y + o.h > y1).map(o => o.id));\n    } else {\n      selectedObjIds.clear();\n    }\n    renderMapObjects(); updateObjEditor();\n    drag = null;\n    return;\n  }\n  drag = null;\n  saveState();\n});\nfunction updateBandRect(a, b){\n  let r = svg.querySelector('#bandRect');\n  if(!r){\n    r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');\n    r.id = 'bandRect';\n    r.setAttribute('fill', 'rgba(36,134,97,.12)');\n    r.setAttribute('stroke', '#248661');\n    svg.appendChild(r);\n  }\n  r.setAttribute('stroke-width', 2/zoom);\n  r.setAttribute('stroke-dasharray', `${4/zoom} ${3/zoom}`);\n  r.setAttribute('x', Math.min(a.x, b.x)); r.setAttribute('y', Math.min(a.y, b.y));\n  r.setAttribute('width', Math.abs(a.x - b.x)); r.setAttribute('height', Math.abs(a.y - b.y));\n}\nfunction removeBandRect(){ const r = svg.querySelector('#bandRect'); if(r) r.remove(); }\n\n/* ===== オブジェクトの右クリックメニュー（複製・削除） ===== */\nsvg.addEventListener('contextmenu', e => {\n  const body = e.target.closest('.obj');\n  if(!body) return;\n  e.preventDefault();\n  if(!selectedObjIds.has(body.dataset.id)){\n    selectedObjIds = new Set([body.dataset.id]);\n    renderMapObjects(); updateObjEditor();\n  }\n  ctx.innerHTML = `<div data-act=\"dup\">⧉ 複製 (Ctrl+D)</div><div data-act=\"delobj\" class=\"danger\">🗑 削除</div>`;\n  ctx.style.display = 'block';\n  ctx.style.left = Math.min(e.clientX, innerWidth - 200) + 'px';\n  ctx.style.top = e.clientY + 'px';\n  ctx.onclick = ev => {\n    const act = ev.target.dataset.act;\n    hideCtx();\n    if(act === 'dup') duplicateSelected();\n    else if(act === 'delobj') deleteSelectedObjs();\n  };\n});\n\n/* ===== ズーム ===== */\nfunction setZoom(z, cx, cy){\n  const sc = $('mapScroll');\n  z = clamp(z, 0.4, 5);\n  const rect = sc.getBoundingClientRect();\n  const ax = (cx == null ? rect.width/2 : cx - rect.left);\n  const ay = (cy == null ? rect.height/2 : cy - rect.top);\n  const px = ax + sc.scrollLeft, py = ay + sc.scrollTop;\n  const ratio = z / zoom;\n  zoom = z;\n  svg.style.width = (zoom*100) + '%';\n  sc.scrollLeft = px * ratio - ax;\n  sc.scrollTop = py * ratio - ay;\n  $('zoomPct').textContent = Math.round(zoom*100) + '%';\n  renderMapObjects(); // 文字・枠線・ハンドルをズームに合わせて再計算\n}\n$('btnZoomIn').onclick = () => setZoom(zoom * 1.25);\n$('btnZoomOut').onclick = () => setZoom(zoom / 1.25);\n$('btnZoomFit').onclick = () => setZoom(1);\n$('mapScroll').addEventListener('wheel', e => {\n  if(!(e.ctrlKey || e.metaKey)) return;\n  e.preventDefault();\n  setZoom(zoom * (e.deltaY < 0 ? 1.15 : 1/1.15), e.clientX, e.clientY);\n}, { passive:false });\n\n/* ===== パネル境界のドラッグリサイズ ===== */\n(function(){\n  const sp = $('splitter'), mp = $('mapPane');\n  let sdrag = null;\n  sp.addEventListener('pointerdown', e => {\n    sdrag = { startX:e.clientX, w:mp.getBoundingClientRect().width };\n    sp.classList.add('active');\n    sp.setPointerCapture(e.pointerId);\n    e.preventDefault();\n  });\n  sp.addEventListener('pointermove', e => {\n    if(!sdrag) return;\n    const total = $('main').getBoundingClientRect().width;\n    const w = clamp(sdrag.w + e.clientX - sdrag.startX, 260, total - 380 - 6);\n    mp.style.flex = 'none';\n    mp.style.width = w + 'px';\n  });\n  sp.addEventListener('pointerup', () => { sdrag = null; sp.classList.remove('active'); });\n  sp.addEventListener('dblclick', () => { mp.style.flex = '1.1'; mp.style.width = ''; }); // ダブルクリックで初期比率に戻す\n})();\n\n/* ===== マップ⇔リストの連動 ===== */\nfunction syncRowHighlight(){\n  let firstTr = null;\n  document.querySelectorAll('#locTable tbody tr[data-obj]').forEach(tr => {\n    const on = selectedObjIds.has(tr.dataset.obj);\n    tr.classList.toggle('hlRow', on);\n    if(on && !firstTr) firstTr = tr;\n  });\n  if(firstTr && selectedObjIds.size >= 1) firstTr.scrollIntoView({ block:'nearest' });\n}\nfunction scrollObjIntoView(id){\n  const st = curStore();\n  const o = st.objects.find(x => x.id === id);\n  if(!o || !st.mapImage) return;\n  const sc = $('mapScroll');\n  const f = svg.getBoundingClientRect().width / st.mapW;\n  sc.scrollTo({ left:(o.x + o.w/2)*f - sc.clientWidth/2, top:(o.y + o.h/2)*f - sc.clientHeight/2, behavior:'smooth' });\n}\n\n/* ===== 画像の取り込み ===== */\nfunction loadImageBlob(blob){\n  const reader = new FileReader();\n  reader.onload = () => {\n    const img = new Image();\n    img.onload = () => {\n      const MAXW = 1600;\n      const scale = Math.min(1, MAXW / img.width);\n      const cv = document.createElement('canvas');\n      cv.width = Math.round(img.width * scale);\n      cv.height = Math.round(img.height * scale);\n      cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);\n      cv.toBlob((outBlob) => {\n        const st = curStore();\n        st.mapImage = URL.createObjectURL(outBlob);\n        st.mapUrl = '';\n        st.mapW = cv.width; st.mapH = cv.height;\n        renderMap(); saveState();\n        toast('マップ画像を設定しました');\n        void uploadMapImageIfPossible(st, outBlob);\n      }, 'image/jpeg', 0.85);\n    };\n    img.src = reader.result;\n  };\n  reader.readAsDataURL(blob);\n}\n/** Supabase Storage（public バケット）へアップロード。他の人にも同じURLで表示される */\nasync function uploadMapImageIfPossible(st, blob){\n  const c = mvpApiConfig();\n  if(!c) return;\n  try {\n    toast('マップ画像をSupabaseへアップロード中…');\n    const result = await mvpUploadMapImage(st.id, blob, `${st.name}.jpg`);\n    if(curStore() && curStore().id === st.id){\n      st.mapUrl = result.mapUrl || '';\n      st.mapFileId = result.mapFileId || '';\n      st.mapImage = result.mapUrl || st.mapImage;\n      renderMap();\n    }\n    saveState();\n    toast('マップ画像をアップロードしました（他の人にも表示されます）');\n  } catch(err){\n    console.warn(err);\n    toast('マップ画像のアップロードに失敗（自分の画面のみ表示・他の人には共有されません）: ' + (err.message || err));\n  }\n}\ndocument.addEventListener('paste', e => {\n  const items = e.clipboardData && e.clipboardData.items;\n  if(!items) return;\n  for(const it of items){\n    if(it.type.startsWith('image/')){ loadImageBlob(it.getAsFile()); e.preventDefault(); return; }\n  }\n});\n$('btnPickImage').onclick = () => $('imageFile').click();\n$('imageFile').onchange = e => { if(e.target.files[0]) loadImageBlob(e.target.files[0]); e.target.value = ''; };\n\n/* ===== オブジェクト追加・削除・属性 ===== */\n/* 配置モード（Googleスライド式）: ボタンを押すと十字カーソルになり、クリックまたはドラッグで配置 */\nlet placeMode = false;\nfunction setPlaceMode(on){\n  placeMode = on;\n  $('mapScroll').classList.toggle('placing', on);\n  $('btnAddObj').classList.toggle('activeMode', on);\n  $('btnAddObj').textContent = on ? '配置中…（Escで中止）' : '＋ オブジェクト追加';\n}\n$('btnAddObj').onclick = () => {\n  const st = curStore();\n  if(!st.mapImage){ toast('先にマップ画像を設定してください'); return; }\n  setPlaceMode(!placeMode);\n  if(placeMode) toast('マップ上をクリック（既定サイズ）またはドラッグ（描いたサイズで配置）します');\n};\nfunction objMinSize(store){\n  // マップ解像度に依らず小さめに（拡大時も細かいオブジェクトを置ける）\n  return Math.max(4, Math.min(10, store.mapW / 500));\n}\nfunction placeObjectAt(start, end){\n  const st = curStore();\n  const MIN = objMinSize(st);\n  // クリック判定は「両辺ともごく小さい」ときだけ。細長いドラッグはサイズ指定として扱う\n  const CLICK = Math.max(MIN + 2, 8);\n  let x = Math.min(start.x, end.x), y = Math.min(start.y, end.y);\n  let w = Math.abs(end.x - start.x), h = Math.abs(end.y - start.y);\n  if(w < CLICK && h < CLICK){\n    // ほぼクリック → クリック位置を中心に既定サイズで配置\n    w = st.mapW / 10;\n    h = st.mapH / 12;\n    x = clamp(end.x - w / 2, 0, st.mapW - w);\n    y = clamp(end.y - h / 2, 0, st.mapH - h);\n  } else {\n    // ドラッグ → 描いたサイズを採用（各辺は MIN 以上にクランプ）\n    w = Math.max(MIN, w);\n    h = Math.max(MIN, h);\n    if(x + w > st.mapW) x = Math.max(0, st.mapW - w);\n    if(y + h > st.mapH) y = Math.max(0, st.mapH - h);\n    x = clamp(x, 0, st.mapW - w);\n    y = clamp(y, 0, st.mapH - h);\n  }\n  const id = uid('obj');\n  st.objects.push({ id, x, y, w, h, category:'', number:null });\n  selectedObjIds = new Set([id]);\n  renderMapObjects(); updateObjEditor(); saveState();\n}\nfunction duplicateSelected(){\n  const st = curStore();\n  const targets = st.objects.filter(o => selectedObjIds.has(o.id));\n  if(!targets.length) return;\n  const off = Math.max(12, st.mapW/60);\n  // グループ全体で同じオフセットを使い、相対位置を維持したまま複製する\n  const offX = Math.max(0, Math.min(off, ...targets.map(o => st.mapW - o.w - o.x)));\n  const offY = Math.max(0, Math.min(off, ...targets.map(o => st.mapH - o.h - o.y)));\n  const used = {};\n  for(const o of st.objects){\n    if(o.category && o.number){ (used[o.category] = used[o.category] || new Set()).add(o.number); }\n  }\n  const clones = [];\n  for(const o of targets){\n    const c = { ...o, id:uid('obj') };\n    delete c.fixture;\n    c.x = o.x + offX;\n    c.y = o.y + offY;\n    if(c.category){\n      const set = used[c.category] = used[c.category] || new Set();\n      let n = 1;\n      while(set.has(n)) n++;\n      c.number = n; set.add(n);\n    }\n    // 全日付のテーマ・什器スケジュールもコピー\n    for(const d of st.dates){\n      const src = cellOf(st, d, o.id);\n      if(src) getAsg(st, d)[c.id] = { theme:src.theme || '', fixture:src.fixture ? { ...src.fixture } : null };\n    }\n    clones.push(c);\n  }\n  st.objects.push(...clones);\n  selectedObjIds = new Set(clones.map(c => c.id));\n  renderAll();\n  toast(`${clones.length}個複製しました（番号は空き番号を自動採番）。そのままドラッグで移動できます`);\n}\nfunction deleteSelectedObjs(){\n  const st = curStore();\n  const ids = [...selectedObjIds].filter(id => st.objects.some(o => o.id === id));\n  if(!ids.length) return;\n  if(!confirm(`選択中の${ids.length}個のオブジェクトを削除しますか？（テーマ設定も削除されます）`)) return;\n  st.objects = st.objects.filter(o => !selectedObjIds.has(o.id));\n  for(const d of Object.keys(st.assignments)) for(const id of ids) delete st.assignments[d][id];\n  selectedCells.forEach(k => { if(ids.includes(k.split('|')[0])) selectedCells.delete(k); });\n  selectedObjIds.clear();\n  renderAll();\n}\n$('btnDupObj').onclick = duplicateSelected;\n$('btnDelObj').onclick = deleteSelectedObjs;\ndocument.addEventListener('keydown', e => {\n  const inInput = /INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName);\n  if((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'd' && !inInput && selectedObjIds.size){\n    duplicateSelected(); e.preventDefault();\n  }\n  if((e.key === 'Delete' || e.key === 'Backspace') && selectedObjIds.size && !inInput){\n    deleteSelectedObjs(); e.preventDefault();\n  }\n  if(e.key === 'Escape'){\n    if(placeMode){ removeBandRect(); setPlaceMode(false); drag = null; }\n    hideCtx(); $('dateModal').classList.remove('show'); $('settingsModal').classList.remove('show');\n  }\n});\n\nfunction singleSelectedObj(){\n  if(selectedObjIds.size !== 1) return null;\n  return curStore().objects.find(x => selectedObjIds.has(x.id)) || null;\n}\n/** 複数オブジェクト選択時に一括テーマ設定する対象日（オブジェクト選択と連動してセルを自動選択する） */\nlet multiApplyDate = null;\nfunction renderMultiDateSelect(){\n  const st = curStore();\n  const dates = [...st.dates].sort();\n  if(!multiApplyDate || !dates.includes(multiApplyDate)) multiApplyDate = dates[dates.length - 1];\n  $('multiDateSel').innerHTML = dates.map(d => `<option value=\"${d}\" ${d===multiApplyDate?'selected':''}>${d}</option>`).join('');\n}\n/** 選択中の複数オブジェクト × 対象日 のセルを一括選択し、右のテーマ適用バーに反映する */\nfunction syncCellsFromObjSelection(){\n  if(!multiApplyDate) return;\n  selectedCells = new Set([...selectedObjIds].map(id => id + '|' + multiApplyDate));\n  renderTable(); updateThemeBar();\n}\n$('multiDateSel').onchange = e => {\n  multiApplyDate = e.target.value;\n  syncCellsFromObjSelection();\n};\nfunction updateObjEditor(){\n  const st = curStore();\n  const ed = $('objEditor');\n  const n = selectedObjIds.size;\n  syncRowHighlight();\n  if(n === 0){ ed.classList.remove('show'); return; }\n  ed.classList.add('show');\n  const o = singleSelectedObj();\n  if(n === 1 && o){\n    $('selInfo').textContent = '選択中:';\n    $('singleEdit').style.display = 'flex';\n    $('multiEdit').style.display = 'none';\n    $('objCategory').value = o.category || '';\n    $('objNumber').value = o.number || '';\n    const dup = dupError(st, o);\n    $('objNumber').classList.toggle('err', dup);\n    $('objErr').textContent = dup ? `⚠ ${o.category} で番号 ${o.number} が重複しています` : '';\n  } else {\n    $('selInfo').textContent = `${n}個選択中（Shift+クリックで追加/解除）`;\n    $('singleEdit').style.display = 'none';\n    $('multiEdit').style.display = 'flex';\n    if(st.dates.length){\n      $('multiDateSel').style.display = '';\n      $('multiDateHint').style.display = 'none';\n      renderMultiDateSelect();\n      syncCellsFromObjSelection();\n    } else {\n      $('multiDateSel').style.display = 'none';\n      $('multiDateHint').style.display = '';\n      selectedCells.clear();\n      renderTable(); updateThemeBar();\n    }\n  }\n}\n$('objCategory').onchange = e => {\n  const o = singleSelectedObj();\n  if(!o) return;\n  o.category = e.target.value;\n  renderAll();\n};\n$('objNumber').oninput = e => {\n  const o = singleSelectedObj();\n  if(!o) return;\n  const v = parseInt(e.target.value, 10);\n  o.number = (v >= 1) ? v : null;\n  renderAll(true);\n};\n\n/* ================= 右側テーブル ================= */\n/* ===== セルの分割（主通路ミッドの表／裏など） =====\n   売場の分割は特定の期間だけ行われ、期間が終われば元の1つに戻る。\n   そのため分割はオブジェクトではなく「セル（ロケーション×日付）」の性質として持つ。\n\n   Supabase の assignments はテーマ列が theme_key の1つしかないため、\n   分割セルのときだけ theme_key に JSON を入れて2テーマ分を格納する。\n     通常   \"盆菓子【BU】\"\n     分割時 {\"s\":\"h\",\"a\":\"盆菓子【BU】\",\"b\":\"秋彼岸【BU】\",\"f2\":{...}}\n   1側の什器は従来どおり fixture_* 列に入り、2側の什器だけ f2 に入れる。\n   アプリ内では { theme, theme2, splitDir, fixture, fixture2 } の素直な形で扱い、\n   Supabase とやり取りする境界だけで変換する。 */\nconst SPLIT_PREFIX = '{\"s\":';\nfunction decodeCellTheme(v){\n  const raw = (v && typeof v === 'object') ? v : { theme: v || '', fixture: null };\n  const t = raw.theme;\n  if(typeof t === 'string' && t.startsWith(SPLIT_PREFIX)){\n    try {\n      const o = JSON.parse(t);\n      if(o && (o.s === 'v' || o.s === 'h')){\n        // 方向の区別はやめたので、旧データの 'v' も上下表示に寄せる\n        return { ...raw, theme: o.a || '', theme2: o.b || '', splitDir: 'h',\n                 fixture2: o.f2 || null };\n      }\n    } catch(e){ /* 壊れていれば通常のテーマ文字列として扱う */ }\n  }\n  return { ...raw, theme: t || '', theme2: '', splitDir: null, fixture2: null };\n}\nfunction encodeCellTheme(c){\n  if(!c) return c;\n  const { theme2, splitDir, fixture2, ...rest } = c;\n  if(splitDir === 'v' || splitDir === 'h'){\n    const j = { s: 'h', a: c.theme || '', b: theme2 || '' };\n    if(fixture2 && fixture2.type) j.f2 = fixture2;\n    return { ...rest, theme: JSON.stringify(j) };\n  }\n  return { ...rest, theme: c.theme || '' };\n}\nfunction decodeAssignments(asg){\n  const out = {};\n  for(const d of Object.keys(asg || {})){\n    out[d] = {};\n    for(const oid of Object.keys(asg[d] || {})) out[d][oid] = decodeCellTheme(asg[d][oid]);\n  }\n  return out;\n}\nfunction encodeAssignments(asg){\n  const out = {};\n  for(const d of Object.keys(asg || {})){\n    out[d] = {};\n    for(const oid of Object.keys(asg[d] || {})) out[d][oid] = encodeCellTheme(asg[d][oid]);\n  }\n  return out;\n}\nconst isSplitCell = c => !!(c && c.splitDir === 'h');\n/** セルキー。分割セルは末尾に枝番を足す（既存の [objId, date] 分解はそのまま通る） */\nconst cellKey = (objId, date, part) => part ? `${objId}|${date}|${part}` : `${objId}|${date}`;\nfunction parseCellKey(k){\n  const a = String(k).split('|');\n  return { objId: a[0], date: a[1], part: a[2] ? Number(a[2]) : 0 };\n}\n/** 分割セルの片側のテーマを読む／書く */\nfunction partTheme(c, part){\n  if(!c) return '';\n  return (isSplitCell(c) && part === 2) ? (c.theme2 || '') : (c.theme || '');\n}\nfunction setPartTheme(c, part, v){\n  if(isSplitCell(c) && part === 2) c.theme2 = v; else c.theme = v;\n}\nfunction partFixture(c, part){\n  if(!c) return null;\n  return (isSplitCell(c) && part === 2) ? (c.fixture2 || null) : (c.fixture || null);\n}\nfunction setPartFixture(c, part, f){\n  if(isSplitCell(c) && part === 2) c.fixture2 = f; else c.fixture = f;\n}\n/** 分割時の既定の什器。種類はそのままに数だけ分け合う（3枚なら 2 と 1） */\nfunction halveFixture(f, side){\n  if(!f || !f.type) return null;\n  const out = { ...f };\n  if(f.count != null && f.count !== ''){\n    const n = Number(f.count) || 0;\n    out.count = side === 1 ? Math.ceil(n / 2) : Math.floor(n / 2);\n  }\n  return out;\n}\n\nfunction getCell(store, date, objId){\n  const m = getAsg(store, date);\n  if(!m[objId]) m[objId] = { theme:'', theme2:'', splitDir:null, fixture:null };\n  else if(typeof m[objId] === 'string') m[objId] = { theme:m[objId], theme2:'', splitDir:null, fixture:null };\n  return m[objId];\n}\nfunction cellOf(store, date, objId){\n  const v = (store.assignments[date] || {})[objId];\n  if(!v) return null;\n  return (typeof v === 'string') ? { theme:v, theme2:'', splitDir:null, fixture:null } : v;\n}\nfunction fixtureDesc(f){\n  if(!f || !f.type) return '';\n  if(isShelfFixtureType(f.type)){\n    const n = f.count != null && f.count !== '' ? Number(f.count) : 1;\n    const countLabel = Number.isFinite(n) && n > 0 ? n : 1;\n    return `${SHELF_FIXTURE_TYPE} ${countLabel}本 ${f.shaku||'?'}尺/${f.heightMm||'?'}mm`;\n  }\n  return `${f.type} ${f.count||'?'}${f.type==='パレット'?'枚':'台'}`;\n}\nfunction renderTable(){\n  const st = curStore();\n  const objs = visibleObjects(st);\n  const dates = [...st.dates].sort();\n  let thead = '<tr><th class=\"fc fc0\"></th><th class=\"fc fc1\">カテゴリ</th><th class=\"fc fc2\">#</th>';\n  for(const d of dates) thead += `<th class=\"dateCol\" data-date=\"${d}\" title=\"${d}（クリックで列を全選択）\">`\n    + `<span class=\"dateLabel\">${fmtDate(d)}</span>`\n    + `<button type=\"button\" class=\"dateMenuBtn\" data-date=\"${d}\" title=\"この日付の挿入・削除\">⋯</button>`\n    + `</th>`;\n  thead += '</tr>';\n  $('locTable').querySelector('thead').innerHTML = thead;\n\n  let tbody = '';\n  let rowNo = 0;\n  for(const o of objs){\n    rowNo++;\n    tbody += `<tr data-obj=\"${o.id}\" class=\"${selectedObjIds.has(o.id)?'hlRow':''}\"><td class=\"fc fc0\" style=\"text-align:center; color:var(--text-secondary)\">${rowNo}</td><td class=\"fc fc1\"><span class=\"catBadge\" style=\"background:${CAT_COLORS[o.category]}\"></span>${esc(o.category)}</td><td class=\"fc fc2\">${o.number}</td>`;\n    for(const d of dates){\n      const c = cellOf(st, d, o.id);\n      const th = c ? (c.theme || '') : '';\n      const fx = c && c.fixture && c.fixture.type ? fixtureDesc(c.fixture) : '';\n      if(isSplitCell(c)){\n        // 分割セル: 3-1 / 3-2 を並べる（v=左右, h=上下）\n        const k1 = cellKey(o.id, d, 1), k2 = cellKey(o.id, d, 2);\n        const t1 = c.theme || '', t2 = c.theme2 || '';\n        const half = (k, t, part) => {\n          const pf = partFixture(c, part);\n          const pfx = pf && pf.type ? fixtureDesc(pf) : '';\n          return `<div class=\"cellPart${selectedCells.has(k)?' selectedCell':''}\" data-part=\"${part}\" title=\"${esc(t)}${pfx ? ' / ' + esc(pfx) : ''}\">`\n            + `<span class=\"partNo\">${o.number}-${part}</span>`\n            + `<span class=\"partTheme\">${t ? esc(themeBaseName(t)) : '<span class=\"empty\">−</span>'}</span>`\n            + (pfx ? `<div class=\"cellFix\">${esc(pfx)}</div>` : '')\n            + `</div>`;\n        };\n        tbody += `<td class=\"themeCell splitCell\" data-obj=\"${o.id}\" data-date=\"${d}\">`\n          + `<div class=\"splitWrap\">${half(k1, t1, 1)}${half(k2, t2, 2)}</div>`\n          + `</td>`;\n        continue;\n      }\n      const key = o.id + '|' + d;\n      const has = th || fx;\n      tbody += `<td class=\"themeCell${selectedCells.has(key)?' selectedCell':''}\" data-obj=\"${o.id}\" data-date=\"${d}\" ${has?'draggable=\"true\"':''} title=\"${esc(th)}${fx ? ' / ' + esc(fx) : ''}\">`\n        + `<div class=\"cellTheme\">${th ? esc(themeBaseName(th)) : '<span class=\"empty\">−</span>'}</div>`\n        + (fx ? `<div class=\"cellFix\">${esc(fx)}</div>` : '')\n        + `</td>`;\n    }\n    tbody += '</tr>';\n  }\n  if(!objs.length){\n    tbody = `<tr><td colspan=\"${3+dates.length}\" style=\"color:var(--text-secondary); padding:14px;\">マップにオブジェクトを配置し、カテゴリと番号を設定すると行が追加されます</td></tr>`;\n  }\n  $('locTable').querySelector('tbody').innerHTML = tbody;\n}\n\n/* ===== セルのコピー（単一セル/複数行ブロック対応） ===== */\nlet copiedBlock = null; // { cells:[{dr, dc, theme, fixture}] } 左上セル基準の相対位置\nfunction copiedDesc(c){\n  const parts = [];\n  if(c.theme) parts.push(c.theme);\n  if(c.fixture && c.fixture.type) parts.push(fixtureDesc(c.fixture));\n  return parts.join(' / ') || '（空）';\n}\nfunction updateCopyChip(){\n  $('fixCopyInfo').style.display = copiedBlock ? 'inline' : 'none';\n  if(!copiedBlock) return;\n  $('fixCopyInfo').textContent = '📋 コピー中: ' + (copiedBlock.cells.length === 1\n    ? copiedDesc(copiedBlock.cells[0])\n    : `${copiedBlock.cells.length}セルのブロック`);\n}\nfunction buildBlock(keys){\n  const st = curStore();\n  const ids = visibleObjects(st).map(o => o.id);\n  const dates = [...st.dates].sort();\n  const items = [];\n  for(const k of keys){\n    const [oid, d] = k.split('|');\n    const r = ids.indexOf(oid), c = dates.indexOf(d);\n    if(r < 0 || c < 0) continue;\n    const cell = cellOf(st, d, oid) || { theme:'', fixture:null };\n    items.push({ r, c, theme:cell.theme || '', fixture:cell.fixture ? { ...cell.fixture } : null });\n  }\n  if(!items.length) return null;\n  const r0 = Math.min(...items.map(i => i.r)), c0 = Math.min(...items.map(i => i.c));\n  return { cells: items.map(i => ({ dr:i.r - r0, dc:i.c - c0, theme:i.theme, fixture:i.fixture })) };\n}\nfunction pasteBlock(anchorKey, mode){ // mode: 'both' | 'theme' | 'fix'\n  const st = curStore();\n  const ids = visibleObjects(st).map(o => o.id);\n  const dates = [...st.dates].sort();\n  const [aoid, ad] = anchorKey.split('|');\n  const r0 = ids.indexOf(aoid), c0 = dates.indexOf(ad);\n  if(r0 < 0 || c0 < 0) return;\n  let n = 0;\n  for(const b of copiedBlock.cells){\n    const r = r0 + b.dr, c = c0 + b.dc;\n    if(r >= ids.length || c >= dates.length) continue;\n    const cell = getCell(st, dates[c], ids[r]);\n    if(mode !== 'fix') cell.theme = b.theme;\n    if(mode !== 'theme') cell.fixture = b.fixture ? { ...b.fixture } : null;\n    n++;\n  }\n  renderTable(); saveState();\n  toast(`${n}セルに貼り付けました` + (n < copiedBlock.cells.length ? '（表の範囲外は除外）' : ''));\n}\n\n/* ===== テーマセルの選択・適用 =====\n   選択操作は Excel に合わせている:\n     通常クリック          … そのセルだけを選択（前の選択は解除）\n     Ctrl/Cmd + クリック   … 1セルずつ追加・解除\n     Shift + クリック      … 起点セルからの範囲選択（同じ列内）\n*/\nlet lastCellClick = null; // {obj, date} Shift範囲選択の起点\nconst isMultiSelect = e => e.ctrlKey || e.metaKey;   // Windows:Ctrl / Mac:Command\nfunction clearCellSelection(){\n  selectedCells.clear();\n  document.querySelectorAll('#locTable .selectedCell')\n    .forEach(el => el.classList.remove('selectedCell'));\n}\n$('locTable').addEventListener('click', e => {\n  // 日付ヘッダーの ⋯ ボタン → 挿入・削除メニュー\n  // stopPropagation しないと document の hideCtx で即閉じてしまう\n  const menuBtn = e.target.closest('.dateMenuBtn');\n  if(menuBtn){\n    e.stopPropagation();\n    const r = menuBtn.getBoundingClientRect();\n    openDateMenu(menuBtn.dataset.date, r.left, r.bottom + 2);\n    return;\n  }\n  // 日付ヘッダークリック → 列の全選択/全解除\n  const thd = e.target.closest('th.dateCol');\n  if(thd){\n    const d = thd.dataset.date;\n    const keys = visibleObjects(curStore()).flatMap(o => {\n      const c = cellOf(curStore(), d, o.id);\n      return isSplitCell(c) ? [cellKey(o.id, d, 1), cellKey(o.id, d, 2)] : [cellKey(o.id, d, 0)];\n    });\n    const allSelected = keys.length && keys.every(k => selectedCells.has(k));\n    if(isMultiSelect(e)){\n      // Ctrl/Cmd+クリック: その列を選択に足す（すべて選択済みなら外す）\n      keys.forEach(k => allSelected ? selectedCells.delete(k) : selectedCells.add(k));\n    } else {\n      // 通常クリック: その列だけの選択に切り替える\n      selectedCells = new Set(allSelected ? [] : keys);\n    }\n    lastCellClick = null;\n    renderTable(); updateThemeBar();\n    return;\n  }\n  const cell = e.target.closest('td.themeCell');\n  if(cell){\n    const obj = cell.dataset.obj, date = cell.dataset.date;\n    const partEl = e.target.closest('.cellPart');\n    const key = cellKey(obj, date, partEl ? Number(partEl.dataset.part) : 0);\n    // Shift+クリック: 同じ列の起点セルとの間を範囲選択\n    if(e.shiftKey && lastCellClick && lastCellClick.date === date && lastCellClick.obj !== obj){\n      const ids = visibleObjects(curStore()).map(o => o.id);\n      const i1 = ids.indexOf(lastCellClick.obj), i2 = ids.indexOf(obj);\n      if(i1 >= 0 && i2 >= 0){\n        for(let i = Math.min(i1,i2); i <= Math.max(i1,i2); i++){\n          const cc = cellOf(curStore(), date, ids[i]);\n          if(isSplitCell(cc)){ selectedCells.add(cellKey(ids[i], date, 1)); selectedCells.add(cellKey(ids[i], date, 2)); }\n          else selectedCells.add(cellKey(ids[i], date, 0));\n        }\n        lastCellClick = { obj, date };\n        renderTable(); updateThemeBar();\n        return;\n      }\n    }\n    const mark = partEl || cell;\n    if(isMultiSelect(e)){\n      // Ctrl/Cmd+クリック: 1セルずつ追加・解除\n      if(selectedCells.has(key)){ selectedCells.delete(key); mark.classList.remove('selectedCell'); }\n      else { selectedCells.add(key); mark.classList.add('selectedCell'); }\n    } else {\n      // 通常クリック: 直前の選択を解除して、このセルだけを選択（Excelと同じ）\n      clearCellSelection();\n      selectedCells.add(key); mark.classList.add('selectedCell');\n    }\n    lastCellClick = { obj, date };\n    updateThemeBar();\n    return;\n  }\n  // 固定列部分のクリック → 対応オブジェクトをマップ上で選択・表示\n  if(/INPUT|SELECT|BUTTON|OPTION/.test(e.target.tagName)) return;\n  const tr = e.target.closest('tbody tr[data-obj]');\n  if(!tr) return;\n  const id = tr.dataset.obj;\n  if(e.shiftKey){\n    selectedObjIds.has(id) ? selectedObjIds.delete(id) : selectedObjIds.add(id);\n  } else {\n    selectedObjIds = new Set([id]);\n  }\n  renderMapObjects(); updateObjEditor();\n  if(selectedObjIds.has(id)) scrollObjIntoView(id);\n});\nfunction updateThemeBar(){\n  const bar = $('themeApplyBar');\n  if(selectedCells.size === 0){ bar.classList.remove('show'); return; }\n  bar.classList.add('show');\n  const st = curStore();\n  const cats = new Set();\n  for(const key of selectedCells){\n    const objId = key.split('|')[0];\n    const o = st.objects.find(x => x.id === objId);\n    if(o && o.category) cats.add(o.category);\n  }\n  const scope = cats.size === 1\n    ? divisionLabelForCategory([...cats][0])\n    : (cats.size > 1 ? '複数カテゴリ（共通テーマのみ）' : 'カテゴリ未設定');\n  $('selCount').textContent = `${selectedCells.size}セル選択中｜${scope}`;\n  themeCombo.setOptions(themesForSelection().map(t => t.name));\n}\n\n/* ===== テーマ選択コンボボックス =====\n   ネイティブの <input list=datalist> は入力欄に残った文字で候補が絞られてしまい、\n   一度テーマを選ぶと他のテーマが選べなくなる。そのため自前のコンボにして\n   「クリック時は常に全件表示、文字を入れたときだけ絞り込む」挙動にする。 */\nconst themeCombo = (() => {\n  const wrap = $('themeCombo'), input = $('themeSelect'), menu = $('themeMenu');\n  let options = [], query = '', active = -1;\n\n  const visible = () => !query ? options\n    : options.filter(o => o.toLowerCase().includes(query.toLowerCase()));\n\n  function render(){\n    const list = visible();\n    menu.innerHTML = list.length\n      ? list.map((o, i) => `<div class=\"opt${i === active ? ' active' : ''}\" role=\"option\" data-i=\"${i}\">${esc(o)}</div>`).join('')\n      : `<div class=\"empty\">${options.length ? '一致するテーマがありません' : '選択可能なテーマがありません'}</div>`;\n  }\n  function open(){ query = ''; active = -1; render(); menu.classList.add('show'); }\n  function close(){ menu.classList.remove('show'); active = -1; }\n  function commit(name){\n    input.value = name; wrap.classList.add('hasValue'); close();\n  }\n  function syncClearBtn(){ wrap.classList.toggle('hasValue', !!input.value); }\n\n  // クリック/フォーカスでは常に全件を出す（入力欄の文字では絞らない）\n  input.addEventListener('focus', open);\n  input.addEventListener('mousedown', () => { if(!menu.classList.contains('show')) setTimeout(open, 0); });\n  input.addEventListener('input', () => { query = input.value; active = -1; syncClearBtn(); render(); menu.classList.add('show'); });\n  input.addEventListener('keydown', e => {\n    const list = visible();\n    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){\n      e.preventDefault();\n      if(!menu.classList.contains('show')) open();\n      if(!list.length) return;\n      active = e.key === 'ArrowDown'\n        ? (active + 1) % list.length\n        : (active - 1 + list.length) % list.length;\n      render();\n      const el = menu.querySelector('.opt.active'); if(el) el.scrollIntoView({block:'nearest'});\n    } else if(e.key === 'Enter'){\n      if(menu.classList.contains('show') && active >= 0 && list[active]){ e.preventDefault(); commit(list[active]); }\n    } else if(e.key === 'Escape'){\n      close();\n    }\n  });\n  menu.addEventListener('mousedown', e => {\n    const opt = e.target.closest('.opt'); if(!opt) return;\n    e.preventDefault();                       // blur より先に確定させる\n    commit(visible()[+opt.dataset.i]);\n  });\n  $('themeComboClear').addEventListener('click', () => {\n    input.value = ''; syncClearBtn(); input.focus(); open();\n  });\n  document.addEventListener('mousedown', e => { if(!wrap.contains(e.target)) close(); });\n\n  return {\n    setOptions(list){ options = list; syncClearBtn(); if(menu.classList.contains('show')) render(); },\n    get value(){ return input.value; },\n  };\n})();\n/** 選択中のセルを上下2つに割る */\nfunction splitCells(){\n  const st = curStore();\n  const targets = new Set([...selectedCells].map(k => {\n    const { objId, date } = parseCellKey(k); return objId + '|' + date;\n  }));\n  if(!targets.size){ toast('分割するセルを選んでください'); return; }\n  let n = 0;\n  for(const t of targets){\n    const [objId, date] = t.split('|');\n    const c = getCell(st, date, objId);\n    if(isSplitCell(c)) continue;      // すでに分割済み\n    const f0 = c.fixture;\n    c.splitDir = 'h'; c.theme2 = '';\n    // 什器は種類をそのままに数を半分ずつに分ける（あとから個別に直せる）\n    c.fixture2 = halveFixture(f0, 2);\n    c.fixture = halveFixture(f0, 1);\n    n++;\n  }\n  selectedCells = new Set([...targets].map(t => t + '|1'));\n  renderTable(); updateThemeBar(); saveState();\n  toast(n ? `${n}セルを分割しました（-1 / -2）` : 'すでに分割されています');\n}\n/** 分割を解除して1つに戻す。2側のテーマは破棄する */\nfunction mergeCells(){\n  const st = curStore();\n  const targets = new Set([...selectedCells].map(k => {\n    const { objId, date } = parseCellKey(k); return objId + '|' + date;\n  }));\n  let n = 0;\n  for(const t of targets){\n    const [objId, date] = t.split('|');\n    const c = getCell(st, date, objId);\n    if(!isSplitCell(c)) continue;\n    c.splitDir = null; c.theme2 = ''; c.fixture2 = null;\n    n++;\n  }\n  if(!n){ toast('分割されたセルを選んでください'); return; }\n  selectedCells = new Set([...targets]);\n  renderTable(); updateThemeBar(); saveState();\n  toast(`${n}セルの分割を解除しました（2側のテーマは破棄されます）`);\n}\n\n$('btnApplyTheme').onclick = () => {\n  const th = $('themeSelect').value.trim();\n  if(!th){ toast('テーマを選択してください'); return; }\n  const base = themeBaseName(th);\n  const allowed = new Set(themesForSelection().map(t => t.name));\n  if(!allowed.has(base)){\n    toast('一覧にないテーマです。候補から選択してください（カテゴリによって選べるテーマが絞り込まれます）');\n    return;\n  }\n  const st = curStore();\n  for(const key of selectedCells){\n    const { objId, date, part } = parseCellKey(key);\n    setPartTheme(getCell(st, date, objId), part, base);\n  }\n  renderTable(); updateThemeBar(); saveState();\n  toast(`${selectedCells.size}セルにテーマを適用しました`);\n};\n/* 什器の入力欄（種別に応じて切替） */\n$('fixTypeSel').onchange = () => {\n  const t = $('fixTypeSel').value;\n  const box = $('fixDetailBox');\n  if(t === 'パレット' || t === 'ベースカート'){\n    box.innerHTML = `<input type=\"number\" id=\"fixCount\" min=\"1\" style=\"width:56px\"> ${t==='パレット'?'枚':'台'}`;\n  } else if(isShelfFixtureType(t)){\n    box.innerHTML = `<input type=\"number\" id=\"fixCount\" min=\"1\" value=\"1\" style=\"width:56px\"> 本 `\n      + `<select id=\"fixShaku\"><option value=\"\">尺</option><option value=\"3\">3尺</option><option value=\"4\">4尺</option></select> `\n      + `高さ<input type=\"number\" id=\"fixHeight\" min=\"0\" step=\"10\" style=\"width:70px\"> mm`;\n  } else {\n    box.innerHTML = '';\n  }\n};\n$('btnApplyFix').onclick = () => {\n  const t = $('fixTypeSel').value;\n  if(!t){ toast('什器を選択してください'); return; }\n  const f = { type:normalizeFixtureType(t), count:null, shaku:null, heightMm:null };\n  if(isShelfFixtureType(t)){\n    const rawCount = $('fixCount') && $('fixCount').value ? +$('fixCount').value : 1;\n    f.count = Number.isFinite(rawCount) && rawCount >= 1 ? rawCount : 1;\n    f.shaku = $('fixShaku') && $('fixShaku').value ? +$('fixShaku').value : null;\n    f.heightMm = $('fixHeight') && $('fixHeight').value ? +$('fixHeight').value : null;\n  } else {\n    f.count = $('fixCount') && $('fixCount').value ? +$('fixCount').value : null;\n  }\n  const st = curStore();\n  for(const key of selectedCells){\n    const { objId, date, part } = parseCellKey(key);\n    setPartFixture(getCell(st, date, objId), part, { ...f });\n  }\n  renderTable(); updateThemeBar(); saveState();\n  toast(`${selectedCells.size}セルに「${fixtureDesc(f)}」を適用しました`);\n};\n$('btnClearCells').onclick = () => {\n  const st = curStore();\n  for(const key of selectedCells){\n    const { objId, date, part } = parseCellKey(key);\n    const c = cellOf(st, date, objId);\n    if(isSplitCell(c) && part){\n      // 分割セルは選んだ側だけ消す。両側とも空になったら分割を解除する\n      setPartTheme(c, part, '');\n      setPartFixture(c, part, null);\n      if(!c.theme && !c.theme2 && !c.fixture && !c.fixture2\n         && selectedCells.has(cellKey(objId, date, part === 1 ? 2 : 1))){\n        c.splitDir = null;\n      }\n    } else if(st.assignments[date]){\n      delete st.assignments[date][objId];\n    }\n  }\n  selectedCells.clear();\n  renderTable(); updateThemeBar(); saveState();\n};\n$('btnSplitCell').onclick = () => splitCells();\n$('btnMergeCells').onclick = mergeCells;\n$('btnDeselect').onclick = () => { selectedCells.clear(); renderTable(); updateThemeBar(); };\n\n/* ===== セルのドラッグコピー ===== */\n$('locTable').addEventListener('dragstart', e => {\n  const cell = e.target.closest('td.themeCell');\n  if(!cell) return;\n  e.dataTransfer.setData('text/plain', cell.dataset.obj + '|' + cell.dataset.date);\n  e.dataTransfer.effectAllowed = 'copy';\n});\n$('locTable').addEventListener('dragover', e => {\n  const cell = e.target.closest('td.themeCell');\n  if(cell){ e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; cell.classList.add('dragOver'); }\n});\n$('locTable').addEventListener('dragleave', e => {\n  const cell = e.target.closest('td.themeCell');\n  if(cell) cell.classList.remove('dragOver');\n});\n$('locTable').addEventListener('drop', e => {\n  const cell = e.target.closest('td.themeCell');\n  if(!cell) return;\n  e.preventDefault();\n  cell.classList.remove('dragOver');\n  const src = e.dataTransfer.getData('text/plain');\n  if(!src || !src.includes('|')) return;\n  const [srcObj, srcDate] = src.split('|');\n  const st = curStore();\n  const c = cellOf(st, srcDate, srcObj);\n  if(!c) return;\n  getAsg(st, cell.dataset.date)[cell.dataset.obj] = { theme:c.theme || '', fixture:c.fixture ? { ...c.fixture } : null };\n  renderTable(); saveState();\n});\n\n/* ================= 日付列 ================= */\nfunction showDateModal({title, min, max, onOk}){\n  $('dateModalTitle').textContent = title;\n  const inp = $('dateInput');\n  inp.value = ''; inp.min = min || ''; inp.max = max || '';\n  $('dateHint').textContent = (min ? `選択可能: ${min} 以降` : '任意の日付を選択できます') + (max ? ` 〜 ${max} まで` : '');\n  $('dateModal').classList.add('show');\n  $('dateOk').onclick = () => {\n    const v = inp.value;\n    if(!v){ toast('日付を選択してください'); return; }\n    if(min && v < min){ toast(`${min} 以降の日付を選択してください`); return; }\n    if(max && v > max){ toast(`${max} 以前の日付を選択してください`); return; }\n    if(curStore().dates.includes(v)){ toast('その日付は既に存在します'); return; }\n    $('dateModal').classList.remove('show');\n    onOk(v);\n  };\n  $('dateCancel').onclick = () => $('dateModal').classList.remove('show');\n}\nfunction insertDate(date){\n  const st = curStore();\n  st.dates.push(date);\n  st.dates.sort();\n  const prevs = st.dates.filter(d => d < date);\n  const prev = prevs.length ? prevs[prevs.length-1] : null;\n  const m = {};\n  if(prev){\n    // 直前日付のテーマ・什器をディープコピーで引き継ぐ\n    for(const [oid, v] of Object.entries(st.assignments[prev] || {})){\n      const c = (typeof v === 'string') ? { theme:v, fixture:null } : v;\n      m[oid] = { theme:c.theme || '', fixture:c.fixture ? { ...c.fixture } : null };\n    }\n  } else {\n    // 最初の日付: 旧データにオブジェクト固定の什器があれば初期値として引き継ぐ\n    for(const o of st.objects){\n      if(o.fixture && o.fixture.type) m[o.id] = { theme:'', fixture:{ ...o.fixture } };\n    }\n  }\n  st.assignments[date] = m;\n  renderTable(); saveState();\n  toast(`${date} の列を追加しました` + (prev ? `（${prev} のテーマ・什器を引き継ぎ）` : ''));\n}\n$('btnAddDate').onclick = () => {\n  const st = curStore();\n  const dates = [...st.dates].sort();\n  const min = dates.length ? addDays(dates[dates.length-1], 1) : null;\n  showDateModal({ title:'売場の開始日を選択', min, max:null, onOk:insertDate });\n};\n\n/* ===== 日付列の右クリック（挿入・削除） ===== */\nconst ctx = $('ctxMenu');\nfunction hideCtx(){ ctx.style.display = 'none'; }\ndocument.addEventListener('click', hideCtx);\n$('locTable').addEventListener('contextmenu', e => {\n  const cellTd = e.target.closest('td.themeCell');\n  if(cellTd){\n    e.preventDefault();\n    const objId = cellTd.dataset.obj, date = cellTd.dataset.date;\n    const st0 = curStore();\n    const partEl0 = e.target.closest('.cellPart');\n    const key = cellKey(objId, date, partEl0 ? Number(partEl0.dataset.part) : 0);\n    const inSelection = selectedCells.size > 0 && selectedCells.has(key);\n    const copyLabel = (inSelection && selectedCells.size > 1) ? `選択中の${selectedCells.size}セルをコピー` : 'セルをコピー';\n    const cc = cellOf(st0, date, objId);\n    const splitItems = isSplitCell(cc)\n      ? `<div data-act=\"cmerge\">⤫ 分割を解除</div>`\n      : `<div data-act=\"csplit\">⬍ 分割（表／裏）</div>`;\n    ctx.innerHTML = splitItems + `<div data-act=\"ccopy\">📋 ${copyLabel}</div>` +\n      (copiedBlock ? `<div data-act=\"cpaste\">📥 貼り付け（テーマ＋什器）</div>\n        <div data-act=\"cpasteT\">└ テーマのみ貼り付け</div>\n        <div data-act=\"cpasteF\">└ 什器のみ貼り付け</div>` : '');\n    ctx.style.display = 'block';\n    ctx.style.left = Math.min(e.clientX, innerWidth - 240) + 'px';\n    ctx.style.top = e.clientY + 'px';\n    ctx.onclick = ev => {\n      const act = ev.target.dataset.act;\n      hideCtx();\n      const st2 = curStore();\n      if(act === 'csplit' || act === 'cmerge'){\n        // 右クリックしたセルが選択外なら、そのセルだけを対象にする\n        if(!selectedCells.has(key)) selectedCells = new Set([key]);\n        if(act === 'cmerge') mergeCells(); else splitCells();\n        return;\n      }\n      if(act === 'ccopy'){\n        copiedBlock = buildBlock(inSelection ? [...selectedCells] : [key]);\n        updateCopyChip();\n        toast(copiedBlock.cells.length === 1\n          ? `「${copiedDesc(copiedBlock.cells[0])}」をコピーしました`\n          : `${copiedBlock.cells.length}セルをブロックとしてコピーしました。貼り付け先の左上セルを右クリックしてください`);\n        return;\n      }\n      if(!act || !copiedBlock) return;\n      const mode = act === 'cpasteT' ? 'theme' : act === 'cpasteF' ? 'fix' : 'both';\n      // 単一セルのコピーで、選択範囲内を右クリックした場合は選択セル全部に貼り付け\n      if(copiedBlock.cells.length === 1 && inSelection){\n        const b = copiedBlock.cells[0];\n        for(const k of selectedCells){\n          const [oid, d] = k.split('|');\n          const c = getCell(st2, d, oid);\n          if(mode !== 'fix') c.theme = b.theme;\n          if(mode !== 'theme') c.fixture = b.fixture ? { ...b.fixture } : null;\n        }\n        renderTable(); saveState();\n        toast(`${selectedCells.size}セルに貼り付けました`);\n        return;\n      }\n      // ブロック貼り付け: 右クリックしたセルを左上として相対位置を維持して貼り付け\n      pasteBlock(key, mode);\n    };\n    return;\n  }\n  const th = e.target.closest('th.dateCol');\n  if(!th) return;\n  e.preventDefault();\n  openDateMenu(th.dataset.date, e.clientX, e.clientY);\n});\n\n/* 日付列のメニュー（右クリック / ヘッダーの ⋯ ボタンの両方から開く） */\nfunction openDateMenu(base, x, y){\n  ctx.innerHTML = `<div data-act=\"insert\">📅 ${base} の後に日付を挿入</div><div data-act=\"del\" class=\"danger\">🗑 この日付列を削除</div>`;\n  ctx.style.display = 'block';\n  ctx.style.left = Math.min(x, innerWidth - 200) + 'px';\n  ctx.style.top = y + 'px';\n  ctx.onclick = ev => {\n    const act = ev.target.dataset.act;\n    hideCtx();\n    const st = curStore();\n    if(act === 'insert'){\n      const dates = [...st.dates].sort();\n      const next = dates.find(d => d > base);\n      const min = addDays(base, 1);\n      const max = next ? addDays(next, -1) : null;\n      if(max && min > max){ toast('挿入できる日付がありません（間が1日もありません）'); return; }\n      showDateModal({ title:`${base} と次の日付の間に挿入`, min, max, onOk:insertDate });\n    } else if(act === 'del'){\n      if(!confirm(`${base} の列を削除しますか？（この日付のテーマ設定も削除されます）`)) return;\n      st.dates = st.dates.filter(d => d !== base);\n      delete st.assignments[base];\n      selectedCells.forEach(k => { if(k.endsWith('|'+base)) selectedCells.delete(k); });\n      renderTable(); updateThemeBar(); saveState();\n      toast(`${base} の列を削除しました`);\n    }\n  };\n}\n\n/* ================= テーマ一覧（MDリスト連携） ================= */\n$('btnSettings').onclick = () => { renderThemeListView(); $('settingsModal').classList.add('show'); };\n$('settingsClose').onclick = () => $('settingsModal').classList.remove('show');\nfunction renderThemeListView(){\n  const themes = uniqueThemesByBase(getMdThemes());\n  if(!themes.length){\n    $('themeListView').innerHTML = '<span style=\"color:#8a919c\">MDリストのテーマが読み込まれていません</span>';\n    return;\n  }\n  const byDiv = {};\n  for(const t of themes){\n    const d = t.division || '（未分類）';\n    (byDiv[d] = byDiv[d] || []).push(t);\n  }\n  const mappingHint =\n    '<div style=\"margin-bottom:10px;font-size:11px;color:var(--text-secondary);line-height:1.7\">' +\n    '日付違いは1テーマとしてまとめ、名称のみ表示します。<br>' +\n    '絞り込み：主通路ミッド＝全テーマ ／ グロ＝グロサリー ／ 菓子＝菓子 ／ 飲料＝飲料 ／ 酒＝酒' +\n    '</div>';\n  const blocks = Object.keys(byDiv).sort().map(div => {\n    const items = byDiv[div].map(t => `・${esc(t.name)}`).join('<br>');\n    return `<div style=\"margin-bottom:12px\"><b style=\"color:var(--text-accent)\">${esc(div)}（${byDiv[div].length}）</b><br>${items}</div>`;\n  });\n  $('themeListView').innerHTML = mappingHint + blocks.join('');\n}\n\n/* ================= 店舗管理 ================= */\nfunction renderStoreSelect(){\n  $('storeSelect').innerHTML = state.stores.map(s => `<option value=\"${s.id}\" ${s.id===state.currentStoreId?'selected':''}>${esc(s.name)}</option>`).join('');\n}\n$('storeSelect').onchange = e => {\n  state.currentStoreId = e.target.value;\n  selectedObjIds.clear(); selectedCells.clear();\n  renderAll();\n};\n$('btnAddStore').onclick = () => {\n  const name = prompt('店舗名を入力してください');\n  if(!name) return;\n  const st = newStore(name.trim());\n  state.stores.push(st);\n  state.currentStoreId = st.id;\n  selectedObjIds.clear(); selectedCells.clear();\n  renderAll(); saveState();\n};\n$('btnRenameStore').onclick = () => {\n  const st = curStore();\n  const name = prompt('新しい店舗名', st.name);\n  if(!name) return;\n  st.name = name.trim();\n  renderStoreSelect(); saveState();\n};\n$('btnDeleteStore').onclick = () => {\n  if(state.stores.length <= 1){ toast('最後の店舗は削除できません'); return; }\n  const st = curStore();\n  if(!confirm(`店舗「${st.name}」を削除しますか？`)) return;\n  state.stores = state.stores.filter(s => s.id !== st.id);\n  state.currentStoreId = state.stores[0].id;\n  selectedObjIds.clear(); selectedCells.clear();\n  renderAll(); saveState();\n  if(mvpApiConfig()) toast('店舗を削除しました（Supabase側の行は残るため、不要な行はSupabaseのTable Editorで手動削除してください）');\n};\n\n/* ================= JSON入出力（1ファイル=1店舗） ================= */\nfunction download(name, blob){\n  const a = document.createElement('a');\n  a.href = URL.createObjectURL(blob);\n  a.download = name;\n  a.click();\n  setTimeout(()=>URL.revokeObjectURL(a.href), 5000);\n}\nfunction exportJson(){\n  const st = curStore();\n  const data = { version:1, app:'baiba-location-tool', themeList:state.themeList, store:st };\n  download(`${st.name}_売場ロケーション.json`, new Blob([JSON.stringify(data)], {type:'application/json'}));\n  toast('JSONを保存しました（共有フォルダ等に置いて共有できます）');\n}\nfunction importJson(){ $('jsonFile').click(); }\n\n/* ================= その他の操作（バックアップ用JSON入出力） ================= */\n$('btnMoreActions').onclick = e => {\n  e.stopPropagation();\n  ctx.innerHTML = '<div data-act=\"exportJson\">💾 JSON保存（バックアップ）</div>' +\n    '<div data-act=\"importJson\">📂 JSON読込（バックアップから復元）</div>';\n  const rect = e.currentTarget.getBoundingClientRect();\n  ctx.style.display = 'block';\n  ctx.style.left = Math.min(rect.left, innerWidth - 240) + 'px';\n  ctx.style.top = rect.bottom + 'px';\n  ctx.onclick = ev => {\n    const act = ev.target.dataset.act;\n    hideCtx();\n    if(act === 'exportJson') exportJson();\n    if(act === 'importJson') importJson();\n  };\n};\n$('jsonFile').onchange = e => {\n  const file = e.target.files[0];\n  if(!file) return;\n  const reader = new FileReader();\n  reader.onload = () => {\n    try {\n      const data = JSON.parse(reader.result);\n      if(!data.store || !Array.isArray(data.store.objects)) throw new Error('bad format');\n      // テーマリストは統合（共通設定）\n      if(Array.isArray(data.themeList)) state.themeList = [...new Set([...state.themeList, ...data.themeList])];\n      const incoming = migrateStore(data.store);\n      const exist = state.stores.find(s => s.name === incoming.name);\n      if(exist){\n        if(!confirm(`同名の店舗「${incoming.name}」が存在します。上書きしますか？`)) return;\n        incoming.id = exist.id;\n        state.stores[state.stores.indexOf(exist)] = incoming;\n      } else {\n        state.stores.push(incoming);\n      }\n      state.currentStoreId = incoming.id;\n      selectedObjIds.clear(); selectedCells.clear();\n      renderAll();\n      toast(`店舗「${incoming.name}」を読み込みました`);\n    } catch(err){ toast('JSONの形式が正しくありません'); }\n  };\n  reader.readAsText(file);\n  e.target.value = '';\n};\n\n/* ================= Excel出力 ================= */\n$('btnExportXlsx').onclick = () => {\n  if(typeof XLSX === 'undefined'){ toast('Excelライブラリの読込に失敗しています（ネット接続を確認）'); return; }\n  const st = curStore();\n  const objs = rowObjects(st);\n  const dates = [...st.dates].sort();\n  const wb = XLSX.utils.book_new();\n\n  const rows1 = [['店舗','カテゴリ','番号']];\n  for(const o of objs) rows1.push([st.name, o.category, o.number]);\n  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows1), 'ロケーション');\n\n  const rows2 = [['カテゴリ','番号', ...dates]];\n  for(const o of objs){\n    rows2.push([o.category, o.number, ...dates.map(d => {\n      const c = cellOf(st, d, o.id);\n      if(!c) return '';\n      return isSplitCell(c) ? `${c.theme || ''} ／ ${c.theme2 || ''}` : (c.theme || '');\n    })]);\n  }\n  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows2), 'テーマスケジュール');\n\n  const rows3 = [['カテゴリ','番号', ...dates.flatMap(d => [d+' 什器', '数量/尺', '高さ(mm)'])]];\n  for(const o of objs){\n    const cols = [];\n    for(const d of dates){\n      const c = cellOf(st, d, o.id);\n      const desc = f => {\n        if(!f || !f.type) return ['', '', ''];\n        if(isShelfFixtureType(f.type)){\n          const n = f.count != null && f.count !== '' ? Number(f.count) : 1;\n          const countLabel = Number.isFinite(n) && n > 0 ? n : 1;\n          const shakuPart = f.shaku ? f.shaku + '尺' : '';\n          return [SHELF_FIXTURE_TYPE, (shakuPart ? shakuPart + '×' : '') + countLabel + '本', f.heightMm ?? ''];\n        }\n        return [f.type, f.count ?? '', ''];\n      };\n      if(isSplitCell(c)){\n        // 分割セルは「A ／ B」で1列にまとめる\n        const a = desc(c.fixture), b = desc(c.fixture2);\n        cols.push(`${a[0]} ／ ${b[0]}`, `${a[1]} ／ ${b[1]}`, `${a[2]} ／ ${b[2]}`);\n      } else {\n        cols.push(...desc(c && c.fixture));\n      }\n    }\n    rows3.push([o.category, o.number, ...cols]);\n  }\n  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows3), '什器スケジュール');\n\n  const ymd = new Date().toISOString().slice(0,10).replace(/-/g,'');\n  XLSX.writeFile(wb, `${st.name}_売場ロケーション_${ymd}.xlsx`);\n};\n\n/* ================= 描画まとめ・初期化 ================= */\nfunction renderAll(skipMapFull){\n  renderStoreSelect();\n  if(skipMapFull) renderMapObjects(); else renderMap();\n  updateObjEditor();\n  renderTable();\n  updateThemeBar();\n  saveState();\n}\n/* 旧データ形式（セル=テーマ文字列、オブジェクト固定の什器）からの移行 */\nfunction migrateStore(st){\n  st.dates = st.dates || [];\n  st.assignments = st.assignments || {};\n  const hasDates = st.dates.length > 0;\n  for(const d of Object.keys(st.assignments)){\n    const m = st.assignments[d];\n    for(const k of Object.keys(m)){\n      if(typeof m[k] === 'string'){\n        const o = st.objects.find(x => x.id === k);\n        m[k] = { theme:m[k], fixture:(o && o.fixture && o.fixture.type) ? normalizeFixture({ ...o.fixture }) : null };\n      } else if(m[k] && typeof m[k] === 'object'){\n        // 旧表記「エンド」を「ゴンドラ」へ寄せる\n        if(m[k].fixture) m[k].fixture = normalizeFixture(m[k].fixture);\n        if(m[k].fixture2) m[k].fixture2 = normalizeFixture(m[k].fixture2);\n      }\n    }\n  }\n  if(hasDates){\n    // 什器が未設定のセルにも旧オブジェクト什器を反映してから、旧プロパティを削除\n    for(const o of st.objects){\n      if(o.fixture && o.fixture.type){\n        const fx = normalizeFixture({ ...o.fixture });\n        for(const d of st.dates){\n          const m = st.assignments[d] = st.assignments[d] || {};\n          if(!m[o.id]) m[o.id] = { theme:'', fixture:fx };\n          else if(!m[o.id].fixture) m[o.id].fixture = { ...fx };\n        }\n      }\n      delete o.fixture;\n    }\n  }\n  return st;\n}\nfunction migrateState(s){\n  if(s && Array.isArray(s.stores)) s.stores.forEach(migrateStore);\n  return s;\n}\nfunction init(){\n  $('objCategory').innerHTML = '<option value=\"\">-- 選択 --</option>' + CATEGORIES.map(c => `<option>${c}</option>`).join('');\n  $('catFilter').innerHTML = '<option value=\"\">すべて</option>' + CATEGORIES.map(c => `<option>${c}</option>`).join('');\n  $('catFilter').onchange = e => {\n    catFilter = e.target.value;\n    selectedCells.clear(); lastCellClick = null;\n    renderTable(); updateThemeBar();\n  };\n  $('numList').innerHTML = Array.from({length:30}, (_,i) => `<option value=\"${i+1}\">`).join('');\n\n  state = migrateState(loadState()) || defaultState();\n  renderAll();\n\n  if(!mvpApiConfig()) return;\n  void (async () => {\n    try {\n      const remote = await loadFromRemote();\n      if(remote && remote.stores.length){\n        const prevStoreId = state && state.currentStoreId;\n        state = migrateState(remote);\n        // 直前まで見ていた店舗がSupabase側にも存在するなら、それを維持する（1行目の店舗に戻さない）\n        if(prevStoreId && state.stores.some(s => s.id === prevStoreId)) state.currentStoreId = prevStoreId;\n        selectedObjIds.clear(); selectedCells.clear();\n        renderAll();\n        toast('Supabaseから読み込みました');\n      }\n    } catch(err){\n      console.warn(err);\n      toast('Supabase読込失敗 → ローカルデータを使用');\n    }\n  })();\n}\ninit();\n<\/script>\n</body>\n</html>\n",C={class:"location-manage"},k={class:"location-manage-title"},j={class:"title"},$={key:0,class:"location-manage-connect"},I={class:"source"},M={key:0,class:"location-manage-error"},T={class:"location-manage-body"},O=["srcdoc"],_=w(d({__name:"index",setup(d){e().initialize();const w=p(()=>n()),_=p(()=>"supabase"===o.value?"Supabase同期中":"ローカルのみ（保存されません）");u(()=>{s()});const E=p(()=>{const e=a.value.length?a.value:i,t=n()?{...r(),user:l(),enabled:!0}:{url:"",key:"",user:"",enabled:!1},o=`window.__MD_THEMES__=${JSON.stringify(e)};`,s=`window.__MVP_API__=${JSON.stringify(t)};`;return S.replace("/* __INJECT_MD_THEMES__ */",o).replace("/* __INJECT_MVP_API__ */",s)}),L=p(()=>{const e=S.includes("フリー売場")?"1":"0";return`loc-${S.length}-${e}`});return(e,n)=>(m(),f("div",C,[b("div",k,[b("span",j,[h(t,{size:"35"}),n[0]||(n[0]=g(" 売場ロケーション ",-1))]),x(w)?(m(),f("div",$,[b("span",I,y(x(_)),1)])):v("",!0)]),x(c)&&"supabase"!==x(o)?(m(),f("p",M,y(x(c)),1)):v("",!0),b("div",T,[(m(),f("iframe",{class:"location-manage-frame",key:x(L),srcdoc:x(E),title:"売場ロケーション管理",sandbox:"allow-scripts allow-same-origin allow-downloads allow-modals allow-forms allow-popups"},null,8,O))])]))}}),[["__scopeId","data-v-e97b7d40"]]);export{_ as default};
